typedef struct lua_State lua_State;
typedef struct TString TString;
typedef struct Table Table;
typedef struct Proto Proto;
typedef struct UpVal UpVal;
typedef struct Closure Closure;
typedef struct GCObject GCObject;
typedef struct TValue TValue;

/* GC object header */
#define GCObject_header  struct GCObject *next; unsigned char tt; unsigned char marked;

struct GCObject {
    GCObject_header
};

/* String object */
struct TString {
    GCObject_header
    unsigned char reserved;
    unsigned char extra;
    unsigned int hash;
    size_t len;
    /* string data follows */
};

#define getstr(ts) ((const char *)((ts) + 1))
#define svalue(o) getstr(tsvalue(o))

/* Value union */
typedef union {
    GCObject *gc;
    void *p;
    lua_Number n;
    int b;
} Value;

struct TValue {
    Value value;
    int tt;
};

#define TValuefields Value value; int tt

/* nil */
#define ttisnil(o)      ((o)->tt == LUA_TNIL)
#define ttisnumber(o)   ((o)->tt == LUA_TNUMBER)
#define ttisstring(o)   ((o)->tt == LUA_TSTRING)
#define ttistable(o)    ((o)->tt == LUA_TTABLE)
#define ttisfunction(o) ((o)->tt == LUA_TFUNCTION)
#define ttisboolean(o)  ((o)->tt == LUA_TBOOLEAN)
#define ttisthread(o)   ((o)->tt == LUA_TTHREAD)
#define ttisuserdata(o) ((o)->tt == LUA_TUSERDATA || (o)->tt == LUA_TLIGHTUSERDATA)
#define ttislightuserdata(o) ((o)->tt == LUA_TLIGHTUSERDATA)
#define ttisfulluserdata(o) ((o)->tt == LUA_TUSERDATA)

