    unsigned short nCcalls;
    unsigned short baseCcalls;
    int hookmask;
    int allowhook;
    int basehookcount;
    int hookcount;
    lua_Hook hook;
    TValue l_gt;  /* table of globals */
    TValue env;
    GCObject *openupval;
    GCObject *gclist;
    struct lua_longjmp *errorJmp;
    ptrdiff_t errfunc;
    /* status */
    int status;
};

typedef void (*lua_Hook)(lua_State *L, lua_Debug *ar);

/* Error handling */
