/* ============================================================
 * STRING TABLE (hash-interned strings)
 * ============================================================ */
#define STRT_INITSIZE 256

static uint32_t str_hash(const char *s, size_t len) {
    uint32_t h = (uint32_t)len;
    size_t step = (len >> 5) + 1;
    for (size_t i = len; i >= step; i -= step)
        h ^= (h << 5) + (h >> 2) + (uint8_t)s[i-1];
    return h;
}

static void strt_init(GState *g) {
    g->strt.size = STRT_INITSIZE;
    g->strt.count = 0;
    g->strt.hash = (LStr**)lmalloc(sizeof(LStr*) * STRT_INITSIZE);
    memset(g->strt.hash, 0, sizeof(LStr*) * STRT_INITSIZE);
}

static void strt_resize(GState *g, int newsize) {
    LStr **newhash = (LStr**)lmalloc(sizeof(LStr*) * newsize);
    memset(newhash, 0, sizeof(LStr*) * newsize);
    for (int i = 0; i < g->strt.size; i++) {
        LStr *s = g->strt.hash[i];
        while (s) {
            LStr *next = (LStr*)s->next;
            int h = s->hash & (newsize - 1);
            s->next = (GCObj*)newhash[h];
            newhash[h] = s;
            s = next;
        }
    }
    lfree(g->strt.hash);
    g->strt.hash = newhash;
    g->strt.size = newsize;
}

static LStr *lstr_new(lua_State *L, const char *s, size_t len) {
    GState *g = G(L);
    uint32_t h = str_hash(s, len);
    int slot = h & (g->strt.size - 1);
    /* Check if already interned */
    for (LStr *ts = g->strt.hash[slot]; ts; ts = (LStr*)ts->next) {
        if (ts->hash == h && ts->len == len && memcmp(lstr_data(ts), s, len) == 0)
            return ts;
    }
    /* Create new string */
    LStr *ts = (LStr*)lmalloc(sizeof(LStr) + len + 1);
    ts->next = (GCObj*)g->strt.hash[slot];
    ts->type = LUA_TSTRING;
    ts->marked = GC_WHITE;
    ts->reserved = 0;
    ts->hash = h;
    ts->len = len;
    memcpy(lstr_data(ts), s, len);
    lstr_data(ts)[len] = '\0';
    g->strt.hash[slot] = ts;
    g->strt.count++;
    /* resize if needed */
    if (g->strt.count > g->strt.size * 2 && g->strt.size < (1<<26)) {
        strt_resize(g, g->strt.size * 2);
    }
    /* Add to allgc */
    ts->next = g->allgc;
    g->allgc = (GCObj*)ts;
    return ts;
}

static LStr *lstr_newz(lua_State *L, const char *s) {
    return lstr_new(L, s, strlen(s));
