    memset(newhash, 0, sizeof(LStr*) * newsize);
    for (int i = 0; i < g->strt.size; i++) {
        LStr *s = g->strt.hash[i];
        while (s) {
            LStr *next = (LStr*)s->next;
            int h = s->hash & (newsize - 1);
            s->next = (GCObj*)newhash[h];
            newhash[h] = s;
            s = next;
        }
