    uint32_t h;
    switch (key->t) {
    case LUA_TNUMBER: {
        double d = key->v.n;
        int i = (int)d;
        if ((double)i == d) h = (uint32_t)i;
        else {
            uint64_t u;
            memcpy(&u, &d, 8);
            h = (uint32_t)(u ^ (u>>32));
        }
        break;
    }
    case LUA_TSTRING:
        h = strval(key)->hash;
        break;
    case LUA_TBOOLEAN:
        h = bval(key) ? 1 : 0;
        break;
    case LUA_TLIGHTUSERDATA:
    case LUA_TFUNCTION:
    case LUA_TTABLE:
    case LUA_TTHREAD:
    case LUA_TUSERDATA: {
        uintptr_t p = (uintptr_t)(key->v.gc);
        h = (uint32_t)(p ^ (p >> 32));
        break;
    }
    default:
        return &DUMMYNODE;
    }
    return &t->node[h & (sz - 1)];
}

static Node *getfreepos(Table *t) {
