    t->sizearray = nasize;

    /* Allocate new hash */
    t->node = (Node*)lmalloc(sizeof(Node) * nhsize);
    for (int i = 0; i < nhsize; i++) {
        tv_nil(&t->node[i].key);
        tv_nil(&t->node[i].val);
        t->node[i].next = NULL;
    }
    t->lsizenode = lsize;
    t->lastfree = &t->node[nhsize - 1];

