static LStr *lstr_new(lua_State *L, const char *s, size_t len) {
    GState *g = G(L);
    uint32_t h = str_hash(s, len);
    int slot = h & (g->strt.size - 1);
    /* Check if already interned */
    for (LStr *ts = g->strt.hash[slot]; ts; ts = (LStr*)ts->next) {
        if (ts->hash == h && ts->len == len && memcmp(lstr_data(ts), s, len) == 0)
            return ts;
    }
    /* Create new string */
    LStr *ts = (LStr*)lmalloc(sizeof(LStr) + len + 1);
    ts->next = (GCObj*)g->strt.hash[slot];
    ts->type = LUA_TSTRING;
    ts->marked = GC_WHITE;
    ts->reserved = 0;
    ts->hash = h;
    ts->len = len;
    memcpy(lstr_data(ts), s, len);
    lstr_data(ts)[len] = '\0';
    g->strt.hash[slot] = ts;
    g->strt.count++;
    /* resize if needed */
    if (g->strt.count > g->strt.size * 2 && g->strt.size < (1<<26)) {
        strt_resize(g, g->strt.size * 2);
    }
    /* Add to allgc */
    ts->next = g->allgc;
    g->allgc = (GCObj*)ts;
    return ts;
}

static LStr *lstr_newz(lua_State *L, const char *s) {
