/* ============================================================
 * TABLE IMPLEMENTATION
 * ============================================================ */
#define MAXBITS 26
#define MAXHSIZE (1<<MAXBITS)

static Table *table_new(lua_State *L) {
    Table *t = lnew(Table);
    t->next = G(L)->allgc;
    G(L)->allgc = (GCObj*)t;
    t->type = LUA_TTABLE;
    t->marked = GC_WHITE;
    t->lsizenode = 0;
    t->metatable = NULL;
    t->array = NULL;
    t->node = &DUMMYNODE;
    t->lastfree = NULL;
    t->sizearray = 0;
    t->gclist = NULL;
    return t;
}

static Node *hashkey(Table *t, const TVal *key) {
    if (isdummy(t->node)) return &DUMMYNODE;
    int sz = sizenode(t);
    uint32_t h;
    switch (key->t) {
    case LUA_TNUMBER: {
        double d = key->v.n;
        int i = (int)d;
        if ((double)i == d) h = (uint32_t)i;
        else {
            uint64_t u;
            memcpy(&u, &d, 8);
            h = (uint32_t)(u ^ (u>>32));
        }
        break;
    }
    case LUA_TSTRING:
        h = strval(key)->hash;
        break;
    case LUA_TBOOLEAN:
        h = bval(key) ? 1 : 0;
        break;
    case LUA_TLIGHTUSERDATA:
    case LUA_TFUNCTION:
    case LUA_TTABLE:
    case LUA_TTHREAD:
    case LUA_TUSERDATA: {
        uintptr_t p = (uintptr_t)(key->v.gc);
        h = (uint32_t)(p ^ (p >> 32));
        break;
    }
    default:
        return &DUMMYNODE;
    }
    return &t->node[h & (sz - 1)];
}

static Node *getfreepos(Table *t) {
    if (!t->lastfree || isdummy(t->node)) return NULL;
    while (t->lastfree >= t->node) {
        if (is_nil(&t->lastfree->key))
            return t->lastfree--;
        t->lastfree--;
    }
    return NULL;
}

static int key_eq(const TVal *a, const TVal *b) {
    if (a->t != b->t) {
        /* number can compare with itself */
        return 0;
    }
    switch (a->t) {
    case LUA_TNIL: return 1;
    case LUA_TBOOLEAN: return a->v.b == b->v.b;
    case LUA_TNUMBER: return a->v.n == b->v.n;
    case LUA_TSTRING: return a->v.gc == b->v.gc; /* interned */
    default: return a->v.gc == b->v.gc;
    }
}

static TVal *table_rawget(Table *t, const TVal *key) {
    if (is_nil(key)) return NULL;
    /* check array part first */
    if (is_num(key)) {
        double d = numval(key);
        int i = (int)d;
        if ((double)i == d && i >= 1 && i <= t->sizearray) {
            TVal *v = &t->array[i-1];
            if (!is_nil(v)) return v;
            return NULL;
        }
    }
    /* hash part */
    if (isdummy(t->node)) return NULL;
    Node *n = hashkey(t, key);
    while (n) {
        if (key_eq(&n->key, key)) return &n->val;
        n = n->next;
    }
    return NULL;
}

static TVal *table_rawget_str(Table *t, LStr *key) {
    TVal k; tv_str(&k, key);
    return table_rawget(t, &k);
}

static TVal *table_rawget_int(Table *t, int idx) {
    if (idx >= 1 && idx <= t->sizearray) {
        TVal *v = &t->array[idx-1];
        if (!is_nil(v)) return v;
        return NULL;
    }
    TVal k; tv_num(&k, (double)idx);
    return table_rawget(t, &k);
}

static void table_resize(lua_State *L, Table *t, int nasize, int nhsize);

static void table_rawset(lua_State *L, Table *t, const TVal *key, const TVal *val) {
    if (is_nil(key)) {
        luaG_runerror(L, "table index is nil");
    }
    if (is_num(key) && isnan(numval(key))) {
        luaG_runerror(L, "table index is NaN");
    }
    /* array part? */
    if (is_num(key)) {
        double d = numval(key);
        int i = (int)d;
        if ((double)i == d && i >= 1 && i <= t->sizearray) {
            tv_copy(&t->array[i-1], val);
            return;
        }
        /* Should we expand array? */
        if ((double)i == d && i > 0 && i <= t->sizearray + 1) {
            if (i > t->sizearray) {
                /* grow array part */
                int newsize = t->sizearray + 1;
                /* possibly double */
                while (newsize < i) newsize *= 2;
                table_resize(L, t, newsize, sizenode(t));
            }
            if (i <= t->sizearray) {
                tv_copy(&t->array[i-1], val);
                return;
            }
        }
    }
    /* hash part */
    if (isdummy(t->node)) {
        table_resize(L, t, t->sizearray, 4);
    }
    Node *n = hashkey(t, key);
    /* Find existing key */
    Node *cur = n;
    while (cur) {
        if (key_eq(&cur->key, key)) {
            tv_copy(&cur->val, val);
            return;
        }
        cur = cur->next;
    }
    /* Insert new key */
    Node *free = getfreepos(t);
    if (!free) {
        /* rehash */
        table_resize(L, t, t->sizearray, sizenode(t) * 2);
        table_rawset(L, t, key, val); /* retry */
        return;
    }
    Node *main_n = hashkey(t, key);
    if (!is_nil(&main_n->key) && hashkey(t, &main_n->key) != main_n) {
        /* main position occupied by someone else */
        /* move occupant to free position */
        tv_copy(&free->key, &main_n->key);
        tv_copy(&free->val, &main_n->val);
        free->next = main_n->next;
        main_n->next = NULL;
        tv_nil(&main_n->key);
        tv_nil(&main_n->val);
        /* now use main_n for new key */
        free = main_n;
    } else {
        free->next = main_n->next;
        main_n->next = free;
    }
    tv_copy(&free->key, key);
    tv_copy(&free->val, val);
}

static void table_rawset_str(lua_State *L, Table *t, LStr *key, const TVal *val) {
    TVal k; tv_str(&k, key);
    table_rawset(L, t, &k, val);
}

static void table_rawset_int(lua_State *L, Table *t, int idx, const TVal *val) {
    if (idx >= 1 && idx <= t->sizearray) {
        tv_copy(&t->array[idx-1], val);
        return;
    }
    TVal k; tv_num(&k, (double)idx);
    table_rawset(L, t, &k, val);
}

static void table_resize(lua_State *L, Table *t, int nasize, int nhsize) {
    /* Grow array part */
    int old_nasize = t->sizearray;
    TVal *old_array = t->array;
    Node *old_node = t->node;
    int old_nhsize = isdummy(t->node) ? 0 : sizenode(t);

    /* New sizes */
    if (nhsize < 1) nhsize = 1;
    /* Round up to power of 2 */
    int lsize = 0;
    while ((1 << lsize) < nhsize) lsize++;
    nhsize = 1 << lsize;

    /* Allocate new arrays */
    if (nasize > 0) {
        t->array = (TVal*)lmalloc(sizeof(TVal) * nasize);
        for (int i = 0; i < nasize; i++) tv_nil(&t->array[i]);
        /* Copy old array */
        int copy = nasize < old_nasize ? nasize : old_nasize;
        for (int i = 0; i < copy; i++)
            tv_copy(&t->array[i], &old_array[i]);
    } else {
        t->array = NULL;
    }
    t->sizearray = nasize;

    /* Allocate new hash */
    t->node = (Node*)lmalloc(sizeof(Node) * nhsize);
    for (int i = 0; i < nhsize; i++) {
        tv_nil(&t->node[i].key);
        tv_nil(&t->node[i].val);
        t->node[i].next = NULL;
    }
    t->lsizenode = lsize;
    t->lastfree = &t->node[nhsize - 1];

    /* Reinsert old array elements that don't fit */
    for (int i = nasize; i < old_nasize; i++) {
        if (!is_nil(&old_array[i])) {
            TVal k; tv_num(&k, (double)(i+1));
            table_rawset(L, t, &k, &old_array[i]);
        }
    }
    if (old_array) lfree(old_array);

    /* Reinsert hash elements */
    /* Process in reverse to maintain order */
    for (int i = old_nhsize - 1; i >= 0; i--) {
        Node *n = &old_node[i];
        if (!is_nil(&n->key)) {
            table_rawset(L, t, &n->key, &n->val);
        }
    }
    if (old_node && old_node != &DUMMYNODE) lfree(old_node);
}

static void table_set(lua_State *L, Table *t, const TVal *key, const TVal *val);
static TVal *table_get(lua_State *L, Table *t, const TVal *key);

static int table_len(Table *t) {
    /* binary search for border */
    int j = t->sizearray;
    if (j > 0 && is_nil(&t->array[j-1])) {
        /* binary search in array part */
        int lo = 0, hi = j;
        while (lo < hi) {
            int m = (lo+hi)/2;
            if (is_nil(&t->array[m])) hi = m;
            else lo = m+1;
        }
        return lo;
    }
    /* check if j is a border */
    if (j == 0) {
        /* check hash part */
        TVal k; tv_num(&k, 1.0);
        if (!table_rawget(t, &k)) return 0;
    }
    /* extend into hash part */
    while (1) {
        j++;
        TVal k; tv_num(&k, (double)j);
        if (!table_rawget(t, &k)) return j-1;
    }
}

static int table_next(lua_State *L, Table *t, TVal *key, TVal *val) {
    /* find next key after 'key' */
    int start = -1;
    if (is_nil(key)) {
        start = -1; /* before array */
    } else {
        /* Find current position */
        if (is_num(key)) {
            double d = numval(key);
            int i = (int)d;
            if ((double)i == d && i >= 1 && i <= t->sizearray) {
                start = i - 1; /* in array */
                /* look for next in array */
                for (int j = i; j < t->sizearray; j++) {
                    if (!is_nil(&t->array[j])) {
                        tv_num(key, (double)(j+1));
                        tv_copy(val, &t->array[j]);
                        return 1;
                    }
                }
                start = t->sizearray + sizenode(t); /* move to hash after array */
                goto hash_part;
            }
        }
        /* Find in hash part */
        if (!isdummy(t->node)) {
            Node *n = hashkey(t, key);
            while (n) {
                if (key_eq(&n->key, key)) {
                    /* found - next is n+1 or next in chain? */
                    /* Actually we need to find position in flat order */
                    int pos = (int)(n - t->node);
                    /* scan from pos+1 */
                    for (int j = pos + 1; j < sizenode(t); j++) {
                        if (!is_nil(&t->node[j].key)) {
                            tv_copy(key, &t->node[j].key);
                            tv_copy(val, &t->node[j].val);
                            return 1;
                        }
                    }
                    return 0;
                }
                n = n->next;
            }
        }
        /* key not found */
        luaG_runerror(L, "invalid key to 'next'");
        return 0;
    }

    /* start from beginning of array */
    for (int i = 0; i < t->sizearray; i++) {
        if (!is_nil(&t->array[i])) {
            tv_num(key, (double)(i+1));
            tv_copy(val, &t->array[i]);
            return 1;
        }
    }
hash_part:
    if (!isdummy(t->node)) {
        for (int i = 0; i < sizenode(t); i++) {
            if (!is_nil(&t->node[i].key)) {
                tv_copy(key, &t->node[i].key);
                tv_copy(val, &t->node[i].val);
                return 1;
            }
        }
    }
    return 0;
}

