#define STACKMARGIN 5

static void stack_init(lua_State *L, int size) {
    L->stack = (TVal*)lmalloc(sizeof(TVal) * size);
    L->stacksize = size;
    L->stack_last = L->stack + size - STACKMARGIN;
    for (int i = 0; i < size; i++) tv_nil(&L->stack[i]);
    L->top = L->stack;
    L->base = L->stack;
}

static void stack_grow(lua_State *L, int need) {
    int newsize = L->stacksize;
    while (newsize - STACKMARGIN < (int)(L->top - L->stack) + need)
        newsize *= 2;
    if (newsize > MAXSTACK) {
        luaG_runerror(L, "stack overflow");
    }
    ptrdiff_t top_off = L->top - L->stack;
    ptrdiff_t base_off = L->base - L->stack;
    L->stack = (TVal*)lrealloc(L->stack, sizeof(TVal) * newsize);
    L->stacksize = newsize;
    L->stack_last = L->stack + newsize - STACKMARGIN;
    L->top = L->stack + top_off;
    L->base = L->stack + base_off;
    /* Initialize new slots */
    for (int i = (int)top_off; i < newsize; i++) tv_nil(&L->stack[i]);
    /* Fix up call info pointers */
    for (CallInfo *ci = L->base_ci; ci <= L->ci; ci++) {
