#define LUA_TNIL     0
#define LUA_TBOOL    1
#define LUA_TLUD     2
#define LUA_TNUM     3
#define LUA_TSTR     4
#define LUA_TTAB     5
#define LUA_TFUNC    6
#define LUA_TUD      7
#define LUA_TTHREAD  8
