#define IS_NIL(o)   ((o)->type==LUA_TNIL)
#define IS_BOOL(o)  ((o)->type==LUA_TBOOL)
#define IS_NUM(o)   ((o)->type==LUA_TNUM)
#define IS_STR(o)   ((o)->type==LUA_TSTR)
#define IS_TAB(o)   ((o)->type==LUA_TTAB)
#define IS_FUNC(o)  ((o)->type==LUA_TFUNC)
#define IS_THREAD(o) ((o)->type==LUA_TTHREAD)
