static void lex_error(Lex*ls,const char*msg) __attribute__((noreturn));
static void lex_error(Lex*ls,const char*msg){
    char buf[256];
    snprintf(buf,sizeof(buf),"%s:%d: %s",lstr_s(ls->src)?lstr_s(ls->src):"?",ls->line,msg);
