static void sbuf_add(Lex*ls,int c){
    if(ls->sbuflen>=ls->sbufsize){
        ls->sbufsize*=2;
        ls->sbuf=(char*)lm_realloc(ls->sbuf,ls->sbufsize);
    }
    ls->sbuf[ls->sbuflen++]=(char)c;
}
