static int lex_advance(Lex*ls){
    if(ls->p>=ls->end) return -1;
    int c=(unsigned char)*ls->p++;
    if(c=='\n') ls->line++;
    return c;
}
static int lex_peek(Lex*ls){
    if(ls->p>=ls->end) return -1;
    return (unsigned char)*ls->p;
}
static int lex_skip(Lex*ls){ return lex_advance(ls); }

static void lex_skip_space(Lex*ls){
    while(ls->p<ls->end){
        int c=lex_peek(ls);
        if(c==' '||c=='\t'||c=='\r'||c=='\n'){ lex_advance(ls); }
        else if(c=='-'&&ls->p+1<ls->end&&ls->p[1]=='-'){
            /* Comment */
            ls->p+=2;
            if(ls->p<ls->end&&*ls->p=='['){
                /* Check for long comment */
                const char*p=ls->p;
                int level=0;
                p++;
                while(p<ls->end&&*p=='='){level++;p++;}
                if(p<ls->end&&*p=='['){
                    /* Long comment */
                    ls->p=p+1;
                    while(ls->p<ls->end){
                        if(*ls->p=='\n') ls->line++;
                        if(*ls->p==']'){
                            int l2=0; const char*q=ls->p+1;
                            while(q<ls->end&&*q=='='){l2++;q++;}
                            if(l2==level&&q<ls->end&&*q==']'){ls->p=q+1;goto done_comment;}
                        }
                        ls->p++;
                    }
                    lex_error(ls,"unfinished long comment");
                }else{
                    ls->p=p;
                    /* Short comment - skip to end of line */
                    while(ls->p<ls->end&&*ls->p!='\n') ls->p++;
                }
            }else{
                /* Short comment */
                while(ls->p<ls->end&&*ls->p!='\n') ls->p++;
            }
            done_comment:;
        }else break;
    }
}

static void lex_readlong(Lex*ls,int level,int is_str){
    sbuf_reset(ls);
    /* skip the first newline if immediately after opening bracket */
    if(ls->p<ls->end&&*ls->p=='\n'){ls->line++;ls->p++;}
    else if(ls->p<ls->end&&*ls->p=='\r'){
        ls->p++;
        if(ls->p<ls->end&&*ls->p=='\n'){ls->p++;ls->line++;}
    }
    while(ls->p<ls->end){
        int c=(unsigned char)*ls->p;
        if(c==']'){
            int l=0; const char*q=ls->p+1;
            while(q<ls->end&&*q=='='){l++;q++;}
            if(l==level&&q<ls->end&&*q==']'){ls->p=q+1;goto done;}
        }
        if(c=='\n') ls->line++;
        sbuf_add(ls,c);
        ls->p++;
    }
    lex_error(ls,"unfinished long string");
done:;
