static void lex_readstr(Lex*ls,int delim){
    sbuf_reset(ls);
    while(1){
        if(ls->p>=ls->end) lex_error(ls,"unfinished string");
        int c=(unsigned char)*ls->p++;
        if(c==delim) break;
        if(c=='\n'||c=='\r') lex_error(ls,"unfinished string");
        if(c=='\\'){
            if(ls->p>=ls->end) lex_error(ls,"unfinished string");
            c=(unsigned char)*ls->p++;
            switch(c){
            case 'a': sbuf_add(ls,'\a'); break;
            case 'b': sbuf_add(ls,'\b'); break;
            case 'f': sbuf_add(ls,'\f'); break;
            case 'n': sbuf_add(ls,'\n'); break;
            case 'r': sbuf_add(ls,'\r'); break;
            case 't': sbuf_add(ls,'\t'); break;
            case 'v': sbuf_add(ls,'\v'); break;
            case '\\': sbuf_add(ls,'\\'); break;
            case '\'': sbuf_add(ls,'\''); break;
            case '"':  sbuf_add(ls,'"'); break;
            case '\n': case '\r':
                if(c=='\r'&&ls->p<ls->end&&*ls->p=='\n') ls->p++;
                ls->line++;
                sbuf_add(ls,'\n'); break;
            case 'x': {
                /* hex escape */
                int h1=(ls->p<ls->end)?*ls->p++:0;
                int h2=(ls->p<ls->end)?*ls->p++:0;
                int v=0;
                if(isxdigit(h1)) v=(isdigit(h1)?h1-'0':tolower(h1)-'a'+10);
                else lex_error(ls,"invalid escape sequence");
                if(isxdigit(h2)) v=v*16+(isdigit(h2)?h2-'0':tolower(h2)-'a'+10);
                else lex_error(ls,"invalid escape sequence");
                sbuf_add(ls,v);
                break;
            }
            case 'z': /* skip whitespace */
                while(ls->p<ls->end&&isspace((unsigned char)*ls->p)){if(*ls->p=='\n')ls->line++;ls->p++;}
                break;
            default:
                if(isdigit(c)){
                    int v=c-'0';
                    if(ls->p<ls->end&&isdigit((unsigned char)*ls->p)){v=v*10+(*ls->p++-'0');}
                    if(ls->p<ls->end&&isdigit((unsigned char)*ls->p)){v=v*10+(*ls->p++-'0');}
                    if(v>255) lex_error(ls,"decimal escape too large");
                    sbuf_add(ls,v);
                }else lex_error(ls,"invalid escape sequence");
            }
        }else sbuf_add(ls,c);
    }
}

static int lex_isdigit(int c,int base){
    if(base==16) return isxdigit(c);
    return c>='0'&&c<'0'+base;
