        if(ls->p<ls->end&&(*ls->p=='e'||*ls->p=='E')){isf=1;sbuf_add(ls,*ls->p++);if(ls->p<ls->end&&(*ls->p=='+'||*ls->p=='-'))sbuf_add(ls,*ls->p++);while(ls->p<ls->end&&isdigit((unsigned char)*ls->p)) sbuf_add(ls,*ls->p++);}
    }
    sbuf_add(ls,'\0');
    char*end;
    double v=strtod(ls->sbuf,&end);
    if(*end!='\0') lex_error(ls,"malformed number");
    t->token=TK_NUMBER; t->numval=v;
}

static void lex_next_raw(Lex*ls, Token*t){
    lex_skip_space(ls);
    if(ls->p>=ls->end){t->token=TK_EOF;return;}
    int c=(unsigned char)*ls->p++;
    switch(c){
    case '+': t->token='+'; return;
    case '*': t->token='*'; return;
    case '%': t->token='%'; return;
    case '^': t->token='^'; return;
    case '&': t->token='&'; return;
    case '|': t->token='|'; return;
    case '(': t->token='('; return;
    case ')': t->token=')'; return;
    case '{': t->token='{'; return;
    case '}': t->token='}'; return;
    case ']': t->token=']'; return;
    case ';': t->token=';'; return;
    case ',': t->token=','; return;
    case '#': t->token='#'; return;
    case '-': t->token='-'; return;
    case '/': t->token='/'; return;
    case '~':
        if(ls->p<ls->end&&*ls->p=='='){ls->p++;t->token=TK_NE;}
        else t->token='~';
        return;
    case '<':
        if(ls->p<ls->end&&*ls->p=='='){ls->p++;t->token=TK_LE;}
        else if(ls->p<ls->end&&*ls->p=='<'){ls->p++;t->token=TK_LE-10;}/*SHL*/
        else t->token='<';
        return;
    case '>':
        if(ls->p<ls->end&&*ls->p=='='){ls->p++;t->token=TK_GE;}
        else if(ls->p<ls->end&&*ls->p=='>'){ls->p++;t->token=TK_GE+10;}/*SHR*/
        else t->token='>';
        return;
    case '=':
        if(ls->p<ls->end&&*ls->p=='='){ls->p++;t->token=TK_EQ;}
        else t->token='=';
        return;
    case ':':
        t->token=':'; return;
    case '.':
        if(ls->p<ls->end&&*ls->p=='.'){
            ls->p++;
            if(ls->p<ls->end&&*ls->p=='.'){ls->p++;t->token=TK_DOTS;}
            else t->token=TK_CONCAT;
        }else if(ls->p<ls->end&&isdigit((unsigned char)*ls->p)){
            ls->p--;
            lex_readnum(ls,t);
        }else t->token='.';
        return;
    case '[': {
        /* Check for long string */
        int level=0;
        const char*pp=ls->p;
        while(pp<ls->end&&*pp=='='){level++;pp++;}
        if(pp<ls->end&&*pp=='['){
            ls->p=pp+1;
            lex_readlong(ls,level,1);
            t->token=TK_STRING;
            t->strval=s_new(ls->L,ls->sbuf,ls->sbuflen);
        }else{
            t->token='[';
        }
        return;
    }
    case '\'': case '"':
        lex_readstr(ls,c);
        t->token=TK_STRING;
        t->strval=s_new(ls->L,ls->sbuf,ls->sbuflen);
        return;
    default:
        if(isdigit(c)){
            ls->p--;
            lex_readnum(ls,t);
            return;
        }
        if(isalpha(c)||c=='_'){
            sbuf_reset(ls);
            sbuf_add(ls,c);
            while(ls->p<ls->end&&(isalnum((unsigned char)*ls->p)||*ls->p=='_')) sbuf_add(ls,*ls->p++);
            sbuf_add(ls,'\0');
            /* Check keywords */
            for(int i=0;KEYWORDS[i].name;i++){
                if(!strcmp(ls->sbuf,KEYWORDS[i].name)){t->token=KEYWORDS[i].tok;return;}
            }
            t->token=TK_NAME;
            t->strval=s_new(ls->L,ls->sbuf,ls->sbuflen-1);
            return;
        }
        { char buf[32]; snprintf(buf,sizeof(buf),"unexpected symbol near '%c'",c);
          lex_error(ls,buf); }
    }
}

static void lex_advance_token(Lex*ls){
    if(ls->la_valid){ls->cur=ls->la;ls->la_valid=0;}
    else lex_next_raw(ls,&ls->cur);
}

static int lex_peek_token(Lex*ls){
    if(!ls->la_valid){lex_next_raw(ls,&ls->la);ls->la_valid=1;}
    return ls->la.token;
}

static void lex_init(Lex*ls,lua_State*L,const char*src,size_t srclen,const char*srcname){
    ls->L=L;
    ls->p=src; ls->end=src+srclen;
    ls->line=1; ls->la_valid=0;
    ls->src=s_newz(L,srcname);
    sbuf_init(ls);
    /* Prime the first token */
    lex_advance_token(ls);
}

static int lex_check(Lex*ls,int tok){ return ls->cur.token==tok; }
static void lex_expect(Lex*ls,int tok){
    if(ls->cur.token!=tok){
        char buf[64];
        if(tok<256) snprintf(buf,sizeof(buf),"'%c' expected near line %d",tok,ls->line);
        else snprintf(buf,sizeof(buf),"syntax error near line %d",ls->line);
        lex_error(ls,buf);
    }
    lex_advance_token(ls);
}
static int lex_test(Lex*ls,int tok){ if(ls->cur.token==tok){lex_advance_token(ls);return 1;} return 0; }

