cat >> /workspace/src/lua.c << 'EOF'

/* ============================================================ */
/* AST NODES */
/* ============================================================ */
typedef enum {
    N_NIL,N_TRUE,N_FALSE,N_NUM,N_STR,N_VA,N_NAME,
    N_INDEX,N_FIELD,N_METHOD,N_CALL,N_FUNC,N_TABLE,
    N_BINOP,N_UNOP,N_CONCAT,
    /* statements */
    N_BLOCK,N_ASSIGN,N_LOCAL,N_DO,N_WHILE,N_REPEAT,
    N_IF,N_FORNUM,N_FORGEN,N_FUNCDEF,N_LOCCLFUN,
    N_RETURN,N_BREAK,N_CALLSTAT,N_GOTO,N_LABEL,
} NodeKind;

typedef struct Node Node;
typedef struct NodeList { Node**items; int n,cap; } NodeList;

static void nl_init(NodeList*nl){ nl->items=NULL; nl->n=nl->cap=0; }
static void nl_push(NodeList*nl,Node*n){
    if(nl->n>=nl->cap){
        nl->cap=nl->cap?nl->cap*2:4;
        nl->items=(Node**)lm_realloc(nl->items,sizeof(Node*)*nl->cap);
    }
    nl->items[nl->n++]=n;
}

struct Node {
    NodeKind kind;
    int line;
    union {
        lua_Number num;
        Str*str;
        struct { int op; Node*left,*right; } binop;
        struct { int op; Node*arg; } unop;
        struct { NodeList targets,values; } assign;
        struct { NodeList names; NodeList values; } local_decl;
        struct { NodeList stmts; } block;
        struct { Node*cond,*body; } loop;
        struct { NodeList conds,bodies; Node*else_body; } if_stmt;
        struct { Str*var; Node*init,*limit,*step,*body; } fornum;
        struct { NodeList vars,iters; Node*body; } forgen;
        struct {
            NodeList params;
            int has_va;
            Node*body;
            Node*name; /* for funcdef */
            int is_method;
        } func;
        struct { Node*fn; Node*self; NodeList args; } call;
        struct { Node*table; Node*key; } index;
        struct { Node*table; Str*field; } field;
        struct { Node*table; Str*method; NodeList args; } method;
        struct { NodeList keys,vals; } table;
        struct { NodeList vals; } ret;
        struct { NodeList parts; } concat;
        struct { Str*name; Node*func; } localfunc;
        struct { Node*name; Node*func; } funcdef;
        struct { Str*name; } label;
        struct { Str*target; } goto_stmt;
    };
};

static Node*node_new(NodeKind kind,int line){
    Node*n=LNEW(Node);
    memset(n,0,sizeof(*n));
    n->kind=kind; n->line=line;
    return n;
}

/* ============================================================ */
/* PARSER */
/* ============================================================ */
typedef struct Parser {
    Lex*ls;
    int nbreak; /* nesting level for break */
    int ngoto;  /* for goto checking */
} Parser;

static Node*parse_expr(Parser*p);
static Node*parse_simpleexpr(Parser*p);
static Node*parse_block(Parser*p);
static Node*parse_stat(Parser*p);
static void parse_exprlist(Parser*p, NodeList*nl);
static void parse_parlist(Parser*p, NodeList*params, int*has_va);
static Node*parse_funcbody(Parser*p, int is_method, int line);
static Node*parse_suffexpr(Parser*p);

static Node*parse_primary(Parser*p){
    Lex*ls=p->ls;
    int line=ls->line;
    switch(ls->cur.token){
    case TK_NAME: {
        Str*s=ls->cur.strval; lex_advance_token(ls);
        Node*n=node_new(N_NAME,line); n->str=s; return n;
    }
    case '(': {
        lex_advance_token(ls);
        Node*e=parse_expr(p);
        lex_expect(ls,')');
        /* Wrap in parens to limit to single value */
        /* We'll handle this at evaluation */
        if(e->kind==N_CALL||e->kind==N_VA||e->kind==N_METHOD){
            /* Create a paren wrapper - reuse unop with special op */
            Node*pn=node_new(N_UNOP,line);
            pn->unop.op=-1; /* paren */
            pn->unop.arg=e;
            return pn;
        }
        return e;
    }
    default:
        lex_error(ls,"unexpected symbol in expression");
    }
}

static void parse_callargs(Parser*p, NodeList*args, int*is_method_str){
    Lex*ls=p->ls;
    if(is_method_str) *is_method_str=0;
    if(ls->cur.token=='('){
        lex_advance_token(ls);
        if(ls->cur.token!=')') parse_exprlist(p,args);
        lex_expect(ls,')');
    }else if(ls->cur.token=='{'){
        Node*t=parse_simpleexpr(p);
        nl_push(args,t);
    }else if(ls->cur.token==TK_STRING){
        Node*n=node_new(N_STR,ls->line); n->str=ls->cur.strval;
        lex_advance_token(ls);
        nl_push(args,n);
    }else{
        lex_error(ls,"function arguments expected");
    }
}

static Node*parse_suffexpr(Parser*p){
    Lex*ls=p->ls;
    Node*e=parse_primary(p);
    while(1){
        int line=ls->line;
        if(ls->cur.token=='.'){
            lex_advance_token(ls);
            if(ls->cur.token!=TK_NAME) lex_error(ls,"identifier expected after '.'");
            Str*fn=ls->cur.strval; lex_advance_token(ls);
            Node*n=node_new(N_FIELD,line); n->field.table=e; n->field.field=fn;
            e=n;
        }else if(ls->cur.token=='['){
            lex_advance_token(ls);
            Node*key=parse_expr(p);
            lex_expect(ls,']');
            Node*n=node_new(N_INDEX,line); n->index.table=e; n->index.key=key;
            e=n;
        }else if(ls->cur.token==':'){
            lex_advance_token(ls);
            if(ls->cur.token!=TK_NAME) lex_error(ls,"method name expected");
            Str*mn=ls->cur.strval; lex_advance_token(ls);
            Node*n=node_new(N_METHOD,line);
            n->method.table=e; n->method.method=mn;
            nl_init(&n->method.args);
            parse_callargs(p,&n->method.args,NULL);
            e=n;
        }else if(ls->cur.token=='('||ls->cur.token=='{'||ls->cur.token==TK_STRING){
            Node*n=node_new(N_CALL,line);
            n->call.fn=e; n->call.self=NULL;
            nl_init(&n->call.args);
            parse_callargs(p,&n->call.args,NULL);
            e=n;
        }else break;
    }
    return e;
}

static Node*parse_table(Parser*p){
    Lex*ls=p->ls;
    int line=ls->line;
    lex_expect(ls,'{');
    Node*n=node_new(N_TABLE,line);
    nl_init(&n->table.keys); nl_init(&n->table.vals);
    while(ls->cur.token!='}'){
        if(ls->cur.token=='['){
            lex_advance_token(ls);
            Node*key=parse_expr(p);
            lex_expect(ls,']');
            lex_expect(ls,'=');
            Node*val=parse_expr(p);
            nl_push(&n->table.keys,key); nl_push(&n->table.vals,val);
        }else if(ls->cur.token==TK_NAME&&lex_peek_token(ls)=='='){
            Str*fn=ls->cur.strval; lex_advance_token(ls); lex_advance_token(ls);
            Node*key=node_new(N_STR,ls->line); key->str=fn;
            Node*val=parse_expr(p);
            nl_push(&n->table.keys,key); nl_push(&n->table.vals,val);
        }else{
            Node*val=parse_expr(p);
            nl_push(&n->table.keys,NULL); /* NULL key = array element */
            nl_push(&n->table.vals,val);
        }
        if(!lex_test(ls,',')&&!lex_test(ls,';')) break;
    }
    lex_expect(ls,'}');
    return n;
}

static Node*parse_funcbody(Parser*p, int is_method, int line){
    Lex*ls=p->ls;
    lex_expect(ls,'(');
    Node*fn=node_new(N_FUNC,line);
    nl_init(&fn->func.params); fn->func.has_va=0;
    if(is_method){
        Node*self=node_new(N_NAME,line); self->str=s_newz(ls->L,"self");
        nl_push(&fn->func.params,self);
    }
    parse_parlist(p,&fn->func.params,&fn->func.has_va);
    lex_expect(ls,')');
    int saved=p->nbreak;
    fn->func.body=parse_block(p);
    p->nbreak=saved;
    lex_expect(ls,TK_END);
    return fn;
}

static void parse_parlist(Parser*p, NodeList*params, int*has_va){
    Lex*ls=p->ls;
    if(ls->cur.token==')'){*has_va=0;return;}
    if(ls->cur.token==TK_DOTS){*has_va=1;lex_advance_token(ls);return;}
    while(1){
        if(ls->cur.token==TK_DOTS){*has_va=1;lex_advance_token(ls);break;}
        if(ls->cur.token!=TK_NAME) lex_error(ls,"name or '...' expected");
        Node*n=node_new(N_NAME,ls->line); n->str=ls->cur.strval;
        lex_advance_token(ls);
        nl_push(params,n);
        if(!lex_test(ls,',')) break;
    }
}

static Node*parse_simpleexpr(Parser*p){
    Lex*ls=p->ls;
    int line=ls->line;
    switch(ls->cur.token){
    case TK_NUMBER:{Node*n=node_new(N_NUM,line);n->num=ls->cur.numval;lex_advance_token(ls);return n;}
    case TK_STRING:{Node*n=node_new(N_STR,line);n->str=ls->cur.strval;lex_advance_token(ls);return n;}
    case TK_NIL:  {lex_advance_token(ls);return node_new(N_NIL,line);}
    case TK_TRUE: {lex_advance_token(ls);return node_new(N_TRUE,line);}
    case TK_FALSE:{lex_advance_token(ls);return node_new(N_FALSE,line);}
    case TK_DOTS: {lex_advance_token(ls);return node_new(N_VA,line);}
    case '{': return parse_table(p);
    case TK_FUNCTION: lex_advance_token(ls); return parse_funcbody(p,0,line);
    default: return parse_suffexpr(p);
    }
}

/* Operator precedence */
typedef struct { int left,right; } OpPri;
static OpPri getpri(int op){
    switch(op){
    case TK_OR:      return (OpPri){1,1};
    case TK_AND:     return (OpPri){2,2};
    case '<': case '>': case TK_LE: case TK_GE: case TK_EQ: case TK_NE: return (OpPri){3,3};
    case TK_CONCAT:  return (OpPri){5,4}; /* right assoc */
    case '+': case '-': return (OpPri){6,6};
    case '*': case '/': case '%': return (OpPri){7,7};
    case '^':        return (OpPri){10,9}; /* right assoc */
    default: return (OpPri){-1,-1};
    }
}

static Node*parse_expr_level(Parser*p, int limit){
    Lex*ls=p->ls;
    int line=ls->line;
    Node*e;
    /* Unary operators */
    if(ls->cur.token==TK_NOT||ls->cur.token=='-'||ls->cur.token=='#'){
        int op=ls->cur.token; lex_advance_token(ls);
        Node*arg=parse_expr_level(p,8); /* unary has priority 8 */
        e=node_new(N_UNOP,line); e->unop.op=op; e->unop.arg=arg;
    }else{
        e=parse_simpleexpr(p);
    }
    /* Binary operators */
    while(1){
        int op=ls->cur.token;
        OpPri pri=getpri(op);
        if(pri.left<0||pri.left<=limit) break;
        lex_advance_token(ls);
        Node*right=parse_expr_level(p,pri.right);
        if(op==TK_CONCAT){
            /* Collect consecutive concats */
            Node*cn=node_new(N_CONCAT,line);
            nl_init(&cn->concat.parts);
            if(e->kind==N_CONCAT) cn->concat.parts=e->concat.parts;
            else nl_push(&cn->concat.parts,e);
            if(right->kind==N_CONCAT){
                for(int i=0;i<right->concat.parts.n;i++) nl_push(&cn->concat.parts,right->concat.parts.items[i]);
            }else nl_push(&cn->concat.parts,right);
            e=cn;
        }else{
            Node*n=node_new(N_BINOP,line);
            n->binop.op=op; n->binop.left=e; n->binop.right=right;
            e=n;
        }
    }
    return e;
}

static Node*parse_expr(Parser*p){ return parse_expr_level(p,0); }

static void parse_exprlist(Parser*p, NodeList*nl){
    nl_push(nl,parse_expr(p));
    while(lex_test(p->ls,',')) nl_push(nl,parse_expr(p));
}

static Node*parse_block(Parser*p){
    Lex*ls=p->ls;
    int line=ls->line;
    Node*blk=node_new(N_BLOCK,line);
    nl_init(&blk->block.stmts);
    while(1){
        int t=ls->cur.token;
        if(t==TK_END||t==TK_ELSE||t==TK_ELSEIF||t==TK_UNTIL||t==TK_EOF) break;
        Node*st=parse_stat(p);
        if(st){
            nl_push(&blk->block.stmts,st);
            if(st->kind==N_RETURN) break;
        }
    }
    return blk;
}

static Node*parse_funcname(Parser*p){
    Lex*ls=p->ls;
    int line=ls->line;
    if(ls->cur.token!=TK_NAME) lex_error(ls,"function name expected");
    Node*n=node_new(N_NAME,line); n->str=ls->cur.strval; lex_advance_token(ls);
    int is_method=0;
    while(ls->cur.token=='.'){
        lex_advance_token(ls);
        if(ls->cur.token!=TK_NAME) lex_error(ls,"identifier expected");
        Str*fn=ls->cur.strval; lex_advance_token(ls);
        Node*f=node_new(N_FIELD,line); f->field.table=n; f->field.field=fn;
        n=f;
    }
    if(ls->cur.token==':'){
        lex_advance_token(ls);
        if(ls->cur.token!=TK_NAME) lex_error(ls,"method name expected");
        Str*mn=ls->cur.strval; lex_advance_token(ls);
        Node*m=node_new(N_FIELD,line); m->field.table=n; m->field.field=mn;
        n=m; is_method=1;
    }
    return n;  /* is_method info lost - caller must track */
}

static Node*parse_stat(Parser*p){
    Lex*ls=p->ls;
    lex_test(ls,';');
    if(ls->cur.token==';') return NULL;
    int line=ls->line;
    switch(ls->cur.token){
    case TK_IF: {
        lex_advance_token(ls);
        Node*n=node_new(N_IF,line);
        nl_init(&n->if_stmt.conds); nl_init(&n->if_stmt.bodies);
        n->if_stmt.else_body=NULL;
        nl_push(&n->if_stmt.conds,parse_expr(p));
        lex_expect(ls,TK_THEN);
        nl_push(&n->if_stmt.bodies,parse_block(p));
        while(ls->cur.token==TK_ELSEIF){
            lex_advance_token(ls);
            nl_push(&n->if_stmt.conds,parse_expr(p));
            lex_expect(ls,TK_THEN);
            nl_push(&n->if_stmt.bodies,parse_block(p));
        }
        if(lex_test(ls,TK_ELSE)) n->if_stmt.else_body=parse_block(p);
        lex_expect(ls,TK_END);
        return n;
    }
    case TK_WHILE: {
        lex_advance_token(ls);
        Node*n=node_new(N_WHILE,line);
        n->loop.cond=parse_expr(p);
        lex_expect(ls,TK_DO);
        p->nbreak++;
        n->loop.body=parse_block(p);
        p->nbreak--;
        lex_expect(ls,TK_END);
        return n;
    }
    case TK_DO: {
        lex_advance_token(ls);
        Node*n=node_new(N_DO,line);
        n->loop.body=parse_block(p);
        lex_expect(ls,TK_END);
        return n;
    }
    case TK_FOR: {
        lex_advance_token(ls);
        if(ls->cur.token!=TK_NAME) lex_error(ls,"variable name expected");
        Str*var=ls->cur.strval; lex_advance_token(ls);
        if(ls->cur.token=='='){
            /* numeric for */
            lex_advance_token(ls);
            Node*n=node_new(N_FORNUM,line);
            n->fornum.var=var;
            n->fornum.init=parse_expr(p);
            lex_expect(ls,',');
            n->fornum.limit=parse_expr(p);
            if(lex_test(ls,',')) n->fornum.step=parse_expr(p);
            else n->fornum.step=NULL;
            lex_expect(ls,TK_DO);
            p->nbreak++;
            n->fornum.body=parse_block(p);
            p->nbreak--;
            lex_expect(ls,TK_END);
            return n;
        }else{
            /* generic for */
            Node*n=node_new(N_FORGEN,line);
            nl_init(&n->forgen.vars); nl_init(&n->forgen.iters);
            Node*v=node_new(N_NAME,line); v->str=var;
            nl_push(&n->forgen.vars,v);
            while(lex_test(ls,',')){
                if(ls->cur.token!=TK_NAME) lex_error(ls,"variable name expected");
                Node*vn=node_new(N_NAME,ls->line); vn->str=ls->cur.strval; lex_advance_token(ls);
                nl_push(&n->forgen.vars,vn);
            }
            lex_expect(ls,TK_IN);
            parse_exprlist(p,&n->forgen.iters);
            lex_expect(ls,TK_DO);
            p->nbreak++;
            n->forgen.body=parse_block(p);
            p->nbreak--;
            lex_expect(ls,TK_END);
            return n;
        }
    }
    case TK_REPEAT: {
        lex_advance_token(ls);
        Node*n=node_new(N_REPEAT,line);
        p->nbreak++;
        n->loop.body=parse_block(p);
        p->nbreak--;
        lex_expect(ls,TK_UNTIL);
        n->loop.cond=parse_expr(p);
        return n;
    }
    case TK_FUNCTION: {
        lex_advance_token(ls);
        /* Check if it's a method (has :) */
        /* Parse func name - peek ahead */
        int is_method=0;
        int line2=ls->line;
        if(ls->cur.token!=TK_NAME) lex_error(ls,"function name expected");
        Str*n0=ls->cur.strval; lex_advance_token(ls);
        Node*fname=node_new(N_NAME,line2); fname->str=n0;
        while(ls->cur.token=='.'){
            lex_advance_token(ls);
            if(ls->cur.token!=TK_NAME) lex_error(ls,"identifier expected");
            Str*fn=ls->cur.strval; lex_advance_token(ls);
            Node*f=node_new(N_FIELD,ls->line); f->field.table=fname; f->field.field=fn;
            fname=f;
        }
        if(ls->cur.token==':'){
            lex_advance_token(ls);
            if(ls->cur.token!=TK_NAME) lex_error(ls,"method name expected");
            Str*mn=ls->cur.strval; lex_advance_token(ls);
            Node*f=node_new(N_FIELD,ls->line); f->field.table=fname; f->field.field=mn;
            fname=f; is_method=1;
        }
        Node*fb=parse_funcbody(p,is_method,line);
        Node*n=node_new(N_FUNCDEF,line);
        n->funcdef.name=fname; n->funcdef.func=fb;
        return n;
    }
    case TK_LOCAL: {
        lex_advance_token(ls);
        if(ls->cur.token==TK_FUNCTION){
            lex_advance_token(ls);
            if(ls->cur.token!=TK_NAME) lex_error(ls,"function name expected");
            Str*fn=ls->cur.strval; lex_advance_token(ls);
            Node*fb=parse_funcbody(p,0,line);
            Node*n=node_new(N_LOCCLFUN,line);
            n->localfunc.name=fn; n->localfunc.func=fb;
            return n;
        }else{
            if(ls->cur.token!=TK_NAME) lex_error(ls,"name expected after 'local'");
            Node*n=node_new(N_LOCAL,line);
            nl_init(&n->local_decl.names); nl_init(&n->local_decl.values);
            while(ls->cur.token==TK_NAME){
                Node*nm=node_new(N_NAME,ls->line); nm->str=ls->cur.strval; lex_advance_token(ls);
                /* Skip attribute <close> etc. */
                if(ls->cur.token=='<'){
                    lex_advance_token(ls);
                    /* skip attribute name */
                    if(ls->cur.token==TK_NAME) lex_advance_token(ls);
                    lex_expect(ls,'>');
                }
                nl_push(&n->local_decl.names,nm);
                if(!lex_test(ls,',')) break;
            }
            if(lex_test(ls,'=')) parse_exprlist(p,&n->local_decl.values);
            return n;
        }
    }
    case TK_RETURN: {
        lex_advance_token(ls);
        Node*n=node_new(N_RETURN,line);
        nl_init(&n->ret.vals);
        if(ls->cur.token!=TK_END&&ls->cur.token!=TK_ELSE&&
           ls->cur.token!=TK_ELSEIF&&ls->cur.token!=TK_UNTIL&&
           ls->cur.token!=TK_EOF&&ls->cur.token!=';'){
            parse_exprlist(p,&n->ret.vals);
        }
        lex_test(ls,';');
        return n;
    }
    case TK_BREAK: {
        if(p->nbreak==0) lex_error(ls,"<break> at line 1 not inside a loop");
        lex_advance_token(ls);
        return node_new(N_BREAK,line);
    }
    case TK_GOTO: {
        lex_advance_token(ls);
        if(ls->cur.token!=TK_NAME) lex_error(ls,"label name expected");
        Node*n=node_new(N_GOTO,line);
        n->goto_stmt.target=ls->cur.strval;
        lex_advance_token(ls);
        return n;
    }
    case TK_NIL: case TK_TRUE: case TK_FALSE: case TK_NUMBER: case TK_STRING:
        lex_error(ls,"syntax error: unexpected token");
    case TK_EOF: return NULL;
    case ';': lex_advance_token(ls); return NULL;
    case TK_DOTS: lex_error(ls,"<...> not inside a vararg function");
    default: {
        /* Assignment or function call */
        int line3=ls->line;
        Node*e=parse_suffexpr(p);
        /* Is it an assignment? */
        if(ls->cur.token==','||ls->cur.token=='='){
            Node*n=node_new(N_ASSIGN,line3);
            nl_init(&n->assign.targets); nl_init(&n->assign.values);
            nl_push(&n->assign.targets,e);
            while(lex_test(ls,',')) nl_push(&n->assign.targets,parse_suffexpr(p));
            lex_expect(ls,'=');
            parse_exprlist(p,&n->assign.values);
            return n;
        }else if(e->kind==N_CALL||e->kind==N_METHOD){
            Node*n=node_new(N_CALLSTAT,line3); n->unop.arg=e; return n;
        }else lex_error(ls,"syntax error: assignment or function call expected");
    }
    }
    return NULL; /* unreachable */
}

/* ============================================================ */
/* COMPILE: Parse source -> AST */
/* ============================================================ */
static Node*lua_parse(lua_State*L,const char*src,size_t srclen,const char*srcname){
    Lex ls={0};
    lex_init(&ls,L,src,srclen,srcname);
    Parser p={0};
    p.ls=&ls; p.nbreak=0;
    Node*ast=parse_block(&p);
    if(ls.cur.token!=TK_EOF){ lex_error(&ls,"unexpected symbol near end"); }
    LFREE(ls.sbuf);
    return ast;
}

