    case ';': lex_advance_token(ls); return NULL;
    case TK_DOTS: lex_error(ls,"<...> not inside a vararg function");
    default: {
        /* Assignment or function call */
        int line3=ls->line;
        Node*e=parse_suffexpr(p);
        /* Is it an assignment? */
        if(ls->cur.token==','||ls->cur.token=='='){
            Node*n=node_new(N_ASSIGN,line3);
            nl_init(&n->assign.targets); nl_init(&n->assign.values);
            nl_push(&n->assign.targets,e);
            while(lex_test(ls,',')) nl_push(&n->assign.targets,parse_suffexpr(p));
            lex_expect(ls,'=');
            parse_exprlist(p,&n->assign.values);
            return n;
        }else if(e->kind==N_CALL||e->kind==N_METHOD){
            Node*n=node_new(N_CALLSTAT,line3); n->unop.arg=e; return n;
        }else lex_error(ls,"syntax error: assignment or function call expected");
    }
    }
    return NULL; /* unreachable */
}

/* ============================================================ */
/* COMPILE: Parse source -> AST */
/* ============================================================ */
static Node*lua_parse(lua_State*L,const char*src,size_t srclen,const char*srcname){
    Lex ls={0};
    lex_init(&ls,L,src,srclen,srcname);
    Parser p={0};
    p.ls=&ls; p.nbreak=0;
    Node*ast=parse_block(&p);
    if(ls.cur.token!=TK_EOF){ lex_error(&ls,"unexpected symbol near end"); }
    LFREE(ls.sbuf);
    return ast;
}

