static int val_eq(lua_State*L,const TVal*a,const TVal*b){
    if(a->type!=b->type){
        if(IS_NUM(a)&&IS_NUM(b)) return NUM_VAL(a)==NUM_VAL(b);
        return 0;
    }
    switch(a->type){
    case LUA_TNIL: return 1;
    case LUA_TBOOL: return B_VAL(a)==B_VAL(b);
    case LUA_TNUM: return NUM_VAL(a)==NUM_VAL(b);
    case LUA_TSTR: return STR_VAL(a)==STR_VAL(b);
    default: {
        if(a->v.gc==b->v.gc) return 1;
