        TVal*mm=get_metamethod(L,a,TM_EQ);
        if(!mm) mm=get_metamethod(L,b,TM_EQ);
        if(mm&&IS_FUNC(mm)){
            TVal args[2]; SET_VAL(&args[0],a); SET_VAL(&args[1],b);
            TVal res; SET_NIL(&res);
            eval_call(L,FUNC_VAL(mm),args,2,&res,1);
