    if(IS_STR(a)&&IS_STR(b)) return str_cmp(STR_VAL(a),STR_VAL(b))<=0;
    TVal*mm=get_mm2(L,a,b,TM_LE);
    if(mm&&IS_FUNC(mm)){
        TVal args[2]; SET_VAL(&args[0],a); SET_VAL(&args[1],b);
        TVal res; SET_NIL(&res);
        eval_call(L,FUNC_VAL(mm),args,2,&res,1);
        return TRUTHY(&res);
    }
    /* try __lt with reversed args */
    mm=get_mm2(L,b,a,TM_LT);
    if(mm&&IS_FUNC(mm)){
        TVal args[2]; SET_VAL(&args[0],b); SET_VAL(&args[1],a);
        TVal res; SET_NIL(&res);
        eval_call(L,FUNC_VAL(mm),args,2,&res,1);
        return !TRUTHY(&res);
    }
    luaG_runerror(L,"attempt to compare %s with %s",
