            /* C function - LuaJIT shows builtin# for builtins */
            snprintf(buf,bufsz,"function: 0x%016llx",(unsigned long long)(uintptr_t)fn->c.f);
        }else{
            snprintf(buf,bufsz,"function: 0x%016llx",(unsigned long long)(uintptr_t)fn);
        }
        return buf;
    }
    case LUA_TTHREAD:
        snprintf(buf,bufsz,"thread: 0x%016llx",(unsigned long long)(uintptr_t)THR_VAL(v));
        return buf;
    case LUA_TUD:
        snprintf(buf,bufsz,"userdata: 0x%016llx",(unsigned long long)(uintptr_t)UD_VAL(v));
        return buf;
    case LUA_TLUD:
        snprintf(buf,bufsz,"userdata: 0x%016llx",(unsigned long long)(uintptr_t)P_VAL(v));
        return buf;
    default:
        snprintf(buf,bufsz,"?");
        return buf;
    }
}

/* Arithmetic operations */
static int val_to_num(const TVal*v,double*n){
    if(IS_NUM(v)){*n=NUM_VAL(v);return 1;}
    if(IS_STR(v)){
        char*end; double d=strtod(str_val(STR_VAL(v)),&end);
        while(*end&&isspace((unsigned char)*end)) end++;
        if(*end=='\0'){*n=d;return 1;}
        /* Try hex */
        if(str_val(STR_VAL(v))[0]=='0'&&(str_val(STR_VAL(v))[1]=='x'||str_val(STR_VAL(v))[1]=='X')){
            unsigned long long x=strtoull(str_val(STR_VAL(v))+2,&end,16);
            if(*end=='\0'){*n=(double)x;return 1;}
        }
    }
    return 0;
}

static double fmod_lua(double a,double b){
    double r=fmod(a,b);
    if(r!=0&&(r<0)!=(b<0)) r+=b;
    return r;
}

static void arith_op(lua_State*L,const TVal*a,const TVal*b,int op,TVal*res){
    double da,db;
    int anum=val_to_num(a,&da);
    int bnum=val_to_num(b,&db);
    if(anum&&bnum){
        double r;
        switch(op){
        case '+': r=da+db; break;
        case '-': r=da-db; break;
        case '*': r=da*db; break;
        case '/': r=da/db; break;
        case '%': r=fmod_lua(da,db); break;
        case '^': r=pow(da,db); break;
        default: r=0;
        }
        SET_NUM(res,r); return;
    }
    /* Try metamethod */
    static const int mm_ops[]={'+',TM_ADD,'-',TM_SUB,'*',TM_MUL,'/',TM_DIV,'%',TM_MOD,'^',TM_POW,0};
    int mmidx=-1;
    for(int i=0;mm_ops[i];i+=2){if(mm_ops[i]==op){mmidx=mm_ops[i+1];break;}}
    if(mmidx>=0){
        TVal*mm=get_mm2(L,a,b,mmidx);
        if(mm&&IS_FUNC(mm)){
            TVal args[2]; SET_VAL(&args[0],a); SET_VAL(&args[1],b);
            eval_call(L,FUNC_VAL(mm),args,2,res,1);
            return;
        }
    }
    const char*op_name="perform arithmetic on";
    if(!anum) luaG_typeerror(L,a,op_name);
    else luaG_typeerror(L,b,op_name);
}

/* String operations */
static int str_concat_check(lua_State*L,const TVal*a,const TVal*b,TVal*res){
    if((IS_STR(a)||IS_NUM(a))&&(IS_STR(b)||IS_NUM(b))){
        char ba[64],bb[64];
        const char*sa=IS_STR(a)?str_val(STR_VAL(a)):val_tostr(L,a,ba,sizeof(ba));
        const char*sb=IS_STR(b)?str_val(STR_VAL(b)):val_tostr(L,b,bb,sizeof(bb));
        int la=(int)strlen(sa),lb=(int)strlen(sb);
        char*buf=(char*)lm_alloc(la+lb+1);
        memcpy(buf,sa,la); memcpy(buf+la,sb,lb); buf[la+lb]='\0';
        SET_STR(res,s_new(L,buf,la+lb));
        LFREE(buf);
        return 1;
    }
    return 0;
}

static void do_concat(lua_State*L,const TVal*a,const TVal*b,TVal*res){
    if(str_concat_check(L,a,b,res)) return;
    /* try metamethod */
    TVal*mm=get_mm2(L,a,b,TM_CONCAT);
    if(mm&&IS_FUNC(mm)){
        TVal args[2]; SET_VAL(&args[0],a); SET_VAL(&args[1],b);
        eval_call(L,FUNC_VAL(mm),args,2,res,1);
        return;
    }
    if(!IS_STR(a)&&!IS_NUM(a)) luaG_typeerror(L,a,"concatenate");
    else luaG_typeerror(L,b,"concatenate");
}

/* Comparison */
static int val_eq(lua_State*L,const TVal*a,const TVal*b){
    if(a->type!=b->type){
        if(IS_NUM(a)&&IS_NUM(b)) return NUM_VAL(a)==NUM_VAL(b);
        return 0;
    }
    switch(a->type){
    case LUA_TNIL: return 1;
    case LUA_TBOOL: return B_VAL(a)==B_VAL(b);
    case LUA_TNUM: return NUM_VAL(a)==NUM_VAL(b);
    case LUA_TSTR: return STR_VAL(a)==STR_VAL(b);
    default: {
        if(a->v.gc==b->v.gc) return 1;
        /* try __eq */
        TVal*mm=get_metamethod(L,a,TM_EQ);
        if(!mm) mm=get_metamethod(L,b,TM_EQ);
        if(mm&&IS_FUNC(mm)){
            TVal args[2]; SET_VAL(&args[0],a); SET_VAL(&args[1],b);
            TVal res; SET_NIL(&res);
            eval_call(L,FUNC_VAL(mm),args,2,&res,1);
            return TRUTHY(&res);
        }
        return 0;
    }
    }
}

static int val_lt(lua_State*L,const TVal*a,const TVal*b){
    if(IS_NUM(a)&&IS_NUM(b)) return NUM_VAL(a)<NUM_VAL(b);
    if(IS_STR(a)&&IS_STR(b)) return str_cmp(STR_VAL(a),STR_VAL(b))<0;
    TVal*mm=get_mm2(L,a,b,TM_LT);
    if(mm&&IS_FUNC(mm)){
        TVal args[2]; SET_VAL(&args[0],a); SET_VAL(&args[1],b);
        TVal res; SET_NIL(&res);
        eval_call(L,FUNC_VAL(mm),args,2,&res,1);
        return TRUTHY(&res);
    }
    luaG_runerror(L,"attempt to compare %s with %s",
        a->type==LUA_TNUM?"number":"non-number",b->type==LUA_TNUM?"number":"non-number");
}

static int val_le(lua_State*L,const TVal*a,const TVal*b){
    if(IS_NUM(a)&&IS_NUM(b)) return NUM_VAL(a)<=NUM_VAL(b);
    if(IS_STR(a)&&IS_STR(b)) return str_cmp(STR_VAL(a),STR_VAL(b))<=0;
    TVal*mm=get_mm2(L,a,b,TM_LE);
    if(mm&&IS_FUNC(mm)){
        TVal args[2]; SET_VAL(&args[0],a); SET_VAL(&args[1],b);
        TVal res; SET_NIL(&res);
        eval_call(L,FUNC_VAL(mm),args,2,&res,1);
        return TRUTHY(&res);
    }
    /* try __lt with reversed args */
    mm=get_mm2(L,b,a,TM_LT);
    if(mm&&IS_FUNC(mm)){
        TVal args[2]; SET_VAL(&args[0],b); SET_VAL(&args[1],a);
        TVal res; SET_NIL(&res);
        eval_call(L,FUNC_VAL(mm),args,2,&res,1);
        return !TRUTHY(&res);
    }
    luaG_runerror(L,"attempt to compare %s with %s",
        a->type==LUA_TNUM?"number":"non-number",b->type==LUA_TNUM?"number":"non-number");
}

/* Length operation */
static int val_len(lua_State*L,const TVal*v){
    TVal*mm=get_metamethod(L,v,TM_LEN);
    if(mm&&IS_FUNC(mm)){
        TVal args[1]; SET_VAL(&args[0],v);
        TVal res; SET_NIL(&res);
        eval_call(L,FUNC_VAL(mm),args,1,&res,1);
        if(IS_NUM(&res)) return(int)NUM_VAL(&res);
        return 0;
    }
    if(IS_STR(v)) return STR_VAL(v)->len;
    if(IS_TAB(v)) return tab_length(TAB_VAL(v));
    luaG_typeerror(L,v,"get length of");
    return 0;
}

