/* ============================================================ */
/* EXPRESSION EVALUATOR */
/* ============================================================ */

/* eval_expr: evaluate expression, store in *out
 * Returns number of values (for multi-return expressions) */
static int eval_expr(lua_State*L,Node*n,Env*env,TVal*out,int want_multi){
    if(!n){ SET_NIL(out); return 1; }
    switch(n->kind){
    case N_NIL: SET_NIL(out); return 1;
    case N_TRUE: SET_BOOL(out,1); return 1;
    case N_FALSE: SET_BOOL(out,0); return 1;
    case N_NUM: SET_NUM(out,n->num); return 1;
    case N_STR: SET_STR(out,n->str); return 1;
    case N_NAME: {
        /* Look up in environment */
        TVal*v=env_get(env,n->str);
        if(v){ SET_VAL(out,v); }
        else{
            /* Check globals */
            TVal*gv=tab_rawget_s(TAB_VAL(&L->globals),n->str);
            if(gv) SET_VAL(out,gv);
            else SET_NIL(out);
        }
        return 1;
    }
    case N_VA: {
        /* Varargs */
        TVal*va=env_get(env,s_newz(L,"..."));
        if(!va||!IS_TAB(va)){ SET_NIL(out); return 1; }
        Tab*vat=TAB_VAL(va);
        TVal*cnt=tab_rawget_s(vat,s_newz(L,"n"));
        int n_va=cnt?((int)NUM_VAL(cnt)):0;
        if(want_multi){
            for(int i=0;i<n_va;i++){
                TVal*v=tab_rawget_i(vat,i+1);
                if(v) SET_VAL(&out[i],v); else SET_NIL(&out[i]);
            }
            return n_va;
        }else{
            if(n_va>0){TVal*v=tab_rawget_i(vat,1);if(v)SET_VAL(out,v);else SET_NIL(out);}
            else SET_NIL(out);
            return 1;
        }
    }
    case N_INDEX: {
        TVal tbl,key;
        eval_expr(L,n->index.table,env,&tbl,0);
        eval_expr(L,n->index.key,env,&key,0);
        L_gettable(L,&tbl,&key,out);
        return 1;
    }
    case N_FIELD: {
        TVal tbl;
        eval_expr(L,n->field.table,env,&tbl,0);
        TVal key; SET_STR(&key,n->field.field);
        L_gettable(L,&tbl,&key,out);
        return 1;
    }
    case N_METHOD: {
        /* obj:method(args) */
        TVal obj;
        eval_expr(L,n->method.table,env,&obj,0);
        TVal key; SET_STR(&key,n->method.method);
        TVal fn; L_gettable(L,&obj,&key,&fn);
        if(!IS_FUNC(&fn)){
            /* Check __call */
            TVal*mm=get_metamethod(L,&fn,TM_CALL);
            if(!mm||!IS_FUNC(mm)) luaG_typeerror(L,&fn,"call");
        }
        /* Collect args: self + args */
        int na=n->method.args.n;
        TVal*args=(TVal*)lm_alloc(sizeof(TVal)*(na+1+256));
        SET_VAL(&args[0],&obj);
        int total_args=1;
        for(int i=0;i<na;i++){
            if(i==na-1&&want_multi){
                /* Last arg may be multi */
                TVal tmp[256];
                int nm=eval_expr(L,n->method.args.items[i],env,tmp,1);
                for(int j=0;j<nm;j++) SET_VAL(&args[total_args++],&tmp[j]);
            }else{
                eval_expr(L,n->method.args.items[i],env,&args[total_args],0);
                total_args++;
            }
        }
        Func*fnp=IS_FUNC(&fn)?FUNC_VAL(&fn):NULL;
        if(!fnp){
            TVal*mm=get_metamethod(L,&fn,TM_CALL);
            if(mm&&IS_FUNC(mm)){
                /* Prepend fn to args */
                TVal*nargs=(TVal*)lm_alloc(sizeof(TVal)*(total_args+1));
                SET_VAL(&nargs[0],&fn);
                for(int i=0;i<total_args;i++) SET_VAL(&nargs[i+1],&args[i]);
                LFREE(args); args=nargs; total_args++;
                fnp=FUNC_VAL(mm);
            }else{
                luaG_typeerror(L,&fn,"call");
            }
        }
        TVal ret[256]; int nret_actual=0;
        if(want_multi){
            eval_call(L,fnp,args,total_args,ret,LUA_MULTRET);
            nret_actual=L->coro_nresults;
            for(int i=0;i<nret_actual;i++) SET_VAL(&out[i],&ret[i]);
        }else{
            eval_call(L,fnp,args,total_args,out,1);
            nret_actual=1;
        }
        LFREE(args);
        return nret_actual;
    }
    case N_CALL: {
        TVal fn;
        eval_expr(L,n->call.fn,env,&fn,0);
        /* Check __call for non-functions */
        Func*fnp=NULL;
        TVal*args_start=NULL;
        int na=n->call.args.n;
        int extra=0;
        if(IS_FUNC(&fn)){
            fnp=FUNC_VAL(&fn);
        }else{
            TVal*mm=get_metamethod(L,&fn,TM_CALL);
            if(mm&&IS_FUNC(mm)){
                fnp=FUNC_VAL(mm); extra=1;
            }else{
                luaG_typeerror(L,&fn,"call");
            }
        }
        TVal*args=(TVal*)lm_alloc(sizeof(TVal)*(na+256+extra));
        int total_args=0;
        if(extra){ SET_VAL(&args[0],&fn); total_args=1; }
        for(int i=0;i<na;i++){
            if(i==na-1){
                TVal tmp[256];
                int nm=eval_expr(L,n->call.args.items[i],env,tmp,1);
                for(int j=0;j<nm;j++) SET_VAL(&args[total_args++],&tmp[j]);
            }else{
                eval_expr(L,n->call.args.items[i],env,&args[total_args],0);
                total_args++;
            }
        }
        TVal ret[256]; int nret_actual=0;
        if(want_multi){
            eval_call(L,fnp,args,total_args,ret,LUA_MULTRET);
            nret_actual=L->coro_nresults;
            for(int i=0;i<nret_actual;i++) SET_VAL(&out[i],&ret[i]);
        }else{
            eval_call(L,fnp,args,total_args,out,1);
            nret_actual=1;
        }
        LFREE(args);
        return nret_actual;
    }
    case N_FUNC: {
        Func*fn=lclosure_new_ast(L,n,env);
        SET_FUNC(out,fn); return 1;
    }
    case N_TABLE: {
        Tab*t=tab_new(L);
        int arr_idx=1;
        for(int i=0;i<n->table.vals.n;i++){
            Node*key_node=n->table.keys.items[i];
            Node*val_node=n->table.vals.items[i];
            if(!key_node){
                /* Array-style */
                if(i==n->table.vals.n-1){
                    /* Last element: expand multi-return */
                    TVal tmp[256];
                    int nm=eval_expr(L,val_node,env,tmp,1);
                    for(int j=0;j<nm;j++){
                        TVal k; SET_NUM(&k,(double)arr_idx++);
                        tab_rawset(L,t,&k,&tmp[j]);
                    }
                }else{
                    TVal v; eval_expr(L,val_node,env,&v,0);
                    TVal k; SET_NUM(&k,(double)arr_idx++);
                    tab_rawset(L,t,&k,&v);
                }
            }else{
                TVal k,v;
                eval_expr(L,key_node,env,&k,0);
                eval_expr(L,val_node,env,&v,0);
                tab_rawset(L,t,&k,&v);
            }
        }
        SET_TAB(out,t); return 1;
    }
    case N_BINOP: {
        int op=n->binop.op;
        if(op==TK_AND){
            eval_expr(L,n->binop.left,env,out,0);
            if(FALSY(out)) return 1;
            return eval_expr(L,n->binop.right,env,out,want_multi);
        }
        if(op==TK_OR){
            eval_expr(L,n->binop.left,env,out,0);
            if(TRUTHY(out)) return 1;
            return eval_expr(L,n->binop.right,env,out,want_multi);
        }
        TVal a,b;
        eval_expr(L,n->binop.left,env,&a,0);
        eval_expr(L,n->binop.right,env,&b,0);
        switch(op){
        case '+': case '-': case '*': case '/': case '%': case '^':
            arith_op(L,&a,&b,op,out); break;
        case TK_EQ: SET_BOOL(out,val_eq(L,&a,&b)); break;
        case TK_NE: SET_BOOL(out,!val_eq(L,&a,&b)); break;
        case '<':   SET_BOOL(out,val_lt(L,&a,&b)); break;
        case '>':   SET_BOOL(out,val_lt(L,&b,&a)); break;
        case TK_LE: SET_BOOL(out,val_le(L,&a,&b)); break;
        case TK_GE: SET_BOOL(out,val_le(L,&b,&a)); break;
        default:    SET_NIL(out); break;
        }
        return 1;
    }
    case N_UNOP: {
        int op=n->unop.op;
        if(op==-1){
            /* Paren wrapper - limit to single value */
            eval_expr(L,n->unop.arg,env,out,0);
            return 1;
        }
        TVal a;
        eval_expr(L,n->unop.arg,env,&a,0);
        switch(op){
        case '-': {
            double d;
            if(val_to_num(&a,&d)){ SET_NUM(out,-d); }
            else{
                TVal*mm=get_metamethod(L,&a,TM_UNM);
                if(mm&&IS_FUNC(mm)){TVal args[1];SET_VAL(&args[0],&a);eval_call(L,FUNC_VAL(mm),args,1,out,1);}
                else luaG_typeerror(L,&a,"perform arithmetic on");
            }
            break;
        }
        case TK_NOT: SET_BOOL(out,FALSY(&a)?1:0); break;
        case '#': SET_NUM(out,(double)val_len(L,&a)); break;
        default: SET_NIL(out); break;
        }
        return 1;
    }
    case N_CONCAT: {
        /* Concatenate all parts */
        int np=n->concat.parts.n;
        if(np==0){ SET_STR(out,s_newz(L,"")); return 1; }
        /* Evaluate all parts */
        TVal*parts=(TVal*)lm_alloc(sizeof(TVal)*np);
        for(int i=0;i<np;i++) eval_expr(L,n->concat.parts.items[i],env,&parts[i],0);
        /* Concat from right to left */
        TVal result; SET_VAL(&result,&parts[np-1]);
        for(int i=np-2;i>=0;i--){
            TVal tmp; do_concat(L,&parts[i],&result,&tmp);
            SET_VAL(&result,&tmp);
        }
        SET_VAL(out,&result);
        LFREE(parts);
        return 1;
    }
    default:
        SET_NIL(out); return 1;
    }
}

/* eval_expr_multi: evaluate expression, return up to maxn values */
static int eval_expr_multi(lua_State*L,Node*n,Env*env,TVal*out,int maxn){
    return eval_expr(L,n,env,out,1);
}

/* Assign to an lvalue */
static void assign_lvalue(lua_State*L,Node*target,Env*env,const TVal*val){
    switch(target->kind){
    case N_NAME: {
        if(!env_assign(env,target->str,val)){
            /* Global */
            tab_rawset_s(L,TAB_VAL(&L->globals),target->str,val);
        }
        break;
    }
    case N_INDEX: {
        TVal tbl,key;
        eval_expr(L,target->index.table,env,&tbl,0);
        eval_expr(L,target->index.key,env,&key,0);
        L_settable(L,&tbl,&key,val);
        break;
    }
    case N_FIELD: {
        TVal tbl;
        eval_expr(L,target->field.table,env,&tbl,0);
        TVal key; SET_STR(&key,target->field.field);
        L_settable(L,&tbl,&key,val);
        break;
    }
    default:
        luaG_runerror(L,"invalid assignment target");
    }
}

/* ============================================================ */
/* STATEMENT EVALUATOR */
/* ============================================================ */

/* Signals for control flow */
#define SIG_NONE   0
#define SIG_BREAK  1
#define SIG_RETURN 2
#define SIG_GOTO   3

typedef struct ExecState {
    int sig;      /* SIG_* */
    TVal retvals[256];
    int nret;
    Str*goto_target;
} ExecState;

static int eval_stat(lua_State*L,Node*n,Env*env,ExecState*st);

static int eval_block(lua_State*L,Node*blk,Env*env,TVal*ret,int*nret){
    ExecState st={0};
    *nret=0;
    if(!blk) return SIG_NONE;
    if(blk->kind!=N_BLOCK) return eval_stat(L,blk,env,&st);

    /* Handle goto by scanning for labels */
    int i=0;
    int n_stmts=blk->block.stmts.n;

    while(i<n_stmts){
        Node*s=blk->block.stmts.items[i];
        int r=eval_stat(L,s,env,&st);
        if(r==SIG_BREAK||r==SIG_RETURN){
            if(r==SIG_RETURN){
                for(int j=0;j<st.nret;j++) SET_VAL(&ret[j],&st.retvals[j]);
                *nret=st.nret;
            }
            return r;
        }
        if(r==SIG_GOTO){
            /* Search for label in current block */
            int found=0;
            for(int j=0;j<n_stmts;j++){
                Node*ls=blk->block.stmts.items[j];
                if(ls->kind==N_LABEL&&ls->label.name==st.goto_target){
                    i=j+1;found=1;break;
                }
            }
            if(!found) return SIG_GOTO; /* propagate up */
            continue;
        }
        i++;
    }
    return SIG_NONE;
}

static int eval_stat(lua_State*L,Node*n,Env*env,ExecState*st){
    if(!n) return SIG_NONE;
    switch(n->kind){
    case N_BLOCK: {
        Env*be=env_new(L,env);
        TVal ret[256]; int nret=0;
        int r=eval_block(L,n,be,ret,&nret);
        if(r==SIG_RETURN){
            for(int i=0;i<nret;i++) SET_VAL(&st->retvals[i],&ret[i]);
            st->nret=nret;
        }
        if(r==SIG_GOTO){ st->goto_target=st->goto_target; }
        return r;
    }
    case N_DO: {
        Env*de=env_new(L,env);
        return eval_block(L,n->loop.body,de,st->retvals,&st->nret);
    }
    case N_ASSIGN: {
        /* Evaluate all values first */
        int nt=n->assign.targets.n;
        int nv=n->assign.values.n;
        TVal vals[256];
        int total_vals=0;
        for(int i=0;i<nv;i++){
            if(i==nv-1){
                TVal tmp[256];
                int nm=eval_expr(L,n->assign.values.items[i],env,tmp,1);
                for(int j=0;j<nm&&total_vals<256;j++) SET_VAL(&vals[total_vals++],&tmp[j]);
            }else{
                eval_expr(L,n->assign.values.items[i],env,&vals[total_vals],0);
                total_vals++;
            }
        }
        /* Assign */
        for(int i=0;i<nt;i++){
            TVal v; SET_NIL(&v);
            if(i<total_vals) SET_VAL(&v,&vals[i]);
            assign_lvalue(L,n->assign.targets.items[i],env,&v);
        }
        return SIG_NONE;
    }
    case N_LOCAL: {
        int nn=n->local_decl.names.n;
        int nv=n->local_decl.values.n;
        TVal vals[256]; int total_vals=0;
        for(int i=0;i<nv;i++){
            if(i==nv-1){
                TVal tmp[256];
                int nm=eval_expr(L,n->local_decl.values.items[i],env,tmp,1);
                for(int j=0;j<nm&&total_vals<256;j++) SET_VAL(&vals[total_vals++],&tmp[j]);
            }else{
                eval_expr(L,n->local_decl.values.items[i],env,&vals[total_vals],0);
                total_vals++;
            }
        }
        for(int i=0;i<nn;i++){
            TVal v; SET_NIL(&v);
            if(i<total_vals) SET_VAL(&v,&vals[i]);
            env_set(env,n->local_decl.names.items[i]->str,&v);
        }
        return SIG_NONE;
    }
    case N_LOCCLFUN: {
        /* local function name = function(...) ... end */
        /* Declare the name first (allows recursion) */
        TVal nil; SET_NIL(&nil);
        env_set(env,n->localfunc.name,&nil);
        Func*fn=lclosure_new_ast(L,n->localfunc.func,env);
        TVal fv; SET_FUNC(&fv,fn);
        env_set(env,n->localfunc.name,&fv);
        return SIG_NONE;
    }
    case N_FUNCDEF: {
        /* function name... = function(...) ... end */
        Func*fn=lclosure_new_ast(L,n->funcdef.func,env);
        TVal fv; SET_FUNC(&fv,fn);
        assign_lvalue(L,n->funcdef.name,env,&fv);
        return SIG_NONE;
    }
    case N_WHILE: {
        Env*we=env_new(L,env);
        while(1){
            TVal cond; eval_expr(L,n->loop.cond,env,&cond,0);
            if(FALSY(&cond)) break;
            Env*be=env_new(L,we);
            int r=eval_block(L,n->loop.body,be,st->retvals,&st->nret);
            if(r==SIG_BREAK) break;
            if(r==SIG_RETURN) return r;
            if(r==SIG_GOTO) return r;
        }
        return SIG_NONE;
    }
    case N_REPEAT: {
        while(1){
            Env*be=env_new(L,env);
            int r=eval_block(L,n->loop.body,be,st->retvals,&st->nret);
            if(r==SIG_BREAK) break;
            if(r==SIG_RETURN) return r;
            if(r==SIG_GOTO) return r;
            TVal cond; eval_expr(L,n->loop.cond,be,&cond,0); /* cond can see loop vars */
            if(TRUTHY(&cond)) break;
        }
        return SIG_NONE;
    }
    case N_IF: {
        for(int i=0;i<n->if_stmt.conds.n;i++){
            TVal cond; eval_expr(L,n->if_stmt.conds.items[i],env,&cond,0);
            if(TRUTHY(&cond)){
                Env*be=env_new(L,env);
                return eval_block(L,n->if_stmt.bodies.items[i],be,st->retvals,&st->nret);
            }
        }
        if(n->if_stmt.else_body){
            Env*be=env_new(L,env);
            return eval_block(L,n->if_stmt.else_body,be,st->retvals,&st->nret);
        }
        return SIG_NONE;
    }
    case N_FORNUM: {
        TVal init_v,limit_v,step_v;
        eval_expr(L,n->fornum.init,env,&init_v,0);
        eval_expr(L,n->fornum.limit,env,&limit_v,0);
        if(n->fornum.step) eval_expr(L,n->fornum.step,env,&step_v,0);
        else SET_NUM(&step_v,1.0);
        double init_d,limit_d,step_d;
        if(!val_to_num(&init_v,&init_d)) luaG_runerror(L,"'for' initial value must be a number");
        if(!val_to_num(&limit_v,&limit_d)) luaG_runerror(L,"'for' limit must be a number");
        if(!val_to_num(&step_v,&step_d)) luaG_runerror(L,"'for' step must be a number");
        if(step_d==0) luaG_runerror(L,"'for' step is zero");
        for(double v=init_d;step_d>0?v<=limit_d:v>=limit_d;v+=step_d){
            Env*be=env_new(L,env);
            TVal vv; SET_NUM(&vv,v);
            env_set(be,n->fornum.var,&vv);
            int r=eval_block(L,n->fornum.body,be,st->retvals,&st->nret);
            if(r==SIG_BREAK) break;
            if(r==SIG_RETURN) return r;
            if(r==SIG_GOTO) return r;
        }
        return SIG_NONE;
    }
    case N_FORGEN: {
        /* Evaluate iter expressions */
        int ni=n->forgen.iters.n;
        TVal iters[3]; for(int i=0;i<3;i++) SET_NIL(&iters[i]);
        int total=0;
        for(int i=0;i<ni;i++){
            if(i==ni-1){
                TVal tmp[256]; int nm=eval_expr(L,n->forgen.iters.items[i],env,tmp,1);
                for(int j=0;j<nm&&total<3;j++) SET_VAL(&iters[total++],&tmp[j]);
            }else if(total<3){
                eval_expr(L,n->forgen.iters.items[i],env,&iters[total++],0);
            }
        }
        /* iters[0] = iter function, iters[1] = state, iters[2] = initial control */
        TVal iter_fn=iters[0], state=iters[1], ctrl=iters[2];
        int nv=n->forgen.vars.n;
        while(1){
            TVal args[2]; SET_VAL(&args[0],&state); SET_VAL(&args[1],&ctrl);
            TVal results[256]; int nr=0;
            if(!IS_FUNC(&iter_fn)) luaG_typeerror(L,&iter_fn,"call");
            eval_call(L,FUNC_VAL(&iter_fn),args,2,results,LUA_MULTRET);
            nr=L->coro_nresults;
            if(nr==0||IS_NIL(&results[0])) break;
            SET_VAL(&ctrl,&results[0]);
            if(IS_NIL(&ctrl)) break;
            Env*be=env_new(L,env);
            for(int i=0;i<nv;i++){
                TVal v; SET_NIL(&v);
                if(i<nr) SET_VAL(&v,&results[i]);
                env_set(be,n->forgen.vars.items[i]->str,&v);
            }
            int r=eval_block(L,n->forgen.body,be,st->retvals,&st->nret);
            if(r==SIG_BREAK) break;
            if(r==SIG_RETURN) return r;
            if(r==SIG_GOTO) return r;
        }
        return SIG_NONE;
    }
    case N_RETURN: {
        int nv=n->ret.vals.n;
        int total=0;
        for(int i=0;i<nv;i++){
            if(i==nv-1){
                TVal tmp[256]; int nm=eval_expr(L,n->ret.vals.items[i],env,tmp,1);
                for(int j=0;j<nm&&total<256;j++) SET_VAL(&st->retvals[total++],&tmp[j]);
            }else{
                eval_expr(L,n->ret.vals.items[i],env,&st->retvals[total],0);
                total++;
            }
        }
        st->nret=total;
        return SIG_RETURN;
    }
    case N_BREAK:
        return SIG_BREAK;
    case N_CALLSTAT: {
        TVal ret; eval_expr(L,n->unop.arg,env,&ret,0);
        return SIG_NONE;
    }
    case N_LABEL:
        return SIG_NONE; /* labels are scanned for separately */
    case N_GOTO:
        st->goto_target=n->goto_stmt.target;
        return SIG_GOTO;
    default:
        return SIG_NONE;
    }
}

