/* ============================================================ */
/* CALL MECHANISM */
/* ============================================================ */

/* Forward decl for coroutines */
static lua_State*coro_new(lua_State*L,Func*fn);

typedef struct BreakSignal { int dummy; } BreakSignal;
typedef struct ReturnSignal { TVal*vals; int n; } ReturnSignal;
typedef struct GotoSignal { Str*label; } GotoSignal;

/* eval_call: call a function, store nret results into ret[] */
static void eval_call(lua_State*L,Func*fn,TVal*args,int nargs,TVal*ret,int nret){
    if(!fn){
        luaG_runerror(L,"attempt to call a nil value");
    }

    /* Check for __call metamethod on non-functions */
    if((uintptr_t)fn < 0x1000){
        /* Invalid pointer - this is an error */
        luaG_runerror(L,"attempt to call a nil value");
    }

    if(L->ncC>=MAXCALLS){
        luaG_runerror(L,"stack overflow");
    }
    L->ncC++;

    if(fn->c.is_c==1){
        /* C function */
        /* Set up stack for C call */
        CHK_STK(L,nargs+20);
        TVal*base=L->top;
        /* Push a dummy function slot */
        SET_FUNC(L->top,fn); L->top++;
        TVal*func_slot=L->top-1;
        /* Push args */
        for(int i=0;i<nargs;i++){ SET_VAL(L->top,&args[i]); L->top++; }
        TVal*old_base=L->base;
        L->base=func_slot+1;
        int old_top_offset=(int)(L->top-L->stk);
        /* Push CI */
        CI*ci=ci_push(L);
        ci->func=func_slot;
        ci->base=L->base;
        ci->top=L->top;
        ci->savedpc=NULL;
        ci->nr=nret;
        CI*old_ci=L->ci;
        /* Call the C function */
        int nr=fn->c.f(L);
        L->ci=old_ci-1; if(L->ci<L->ci0)L->ci=L->ci0;
        /* Collect results */
        TVal*results=L->top-nr;
        if(nret>=0){
            for(int i=0;i<nret&&i<nr;i++) SET_VAL(&ret[i],&results[i]);
            for(int i=nr;i<nret;i++) SET_NIL(&ret[i]);
        }else{
            /* LUA_MULTRET */
            for(int i=0;i<nr;i++) SET_VAL(&ret[i],&results[i]);
            /* caller needs to know how many */
            /* We encode count in nret via a different mechanism */
        }
        L->top=base;
        L->base=old_base;
        L->ncC--;
    }else if(fn->c.is_c==0){
        /* Lua bytecode function - not implemented in this interpreter */
        luaG_runerror(L,"bytecode functions not supported");
    }else if(fn->c.is_c==2){
        /* AST closure */
        LuaClosure*cl=(LuaClosure*)fn;
        /* Create new environment */
        Env*env=env_new(L,cl->env);
        /* Bind parameters */
        NodeList*params=&cl->params;
        for(int i=0;i<params->n;i++){
            Str*pname=params->items[i]->str;
            TVal arg; SET_NIL(&arg);
            if(i<nargs) SET_VAL(&arg,&args[i]);
            env_set(env,pname,&arg);
        }
        /* Handle varargs */
        if(cl->has_va){
            /* Store varargs as special "..." entry */
            /* Create a table with varargs */
            Tab*va_tab=tab_new(L);
            int va_start=params->n;
            int va_count=nargs-va_start;
            if(va_count<0) va_count=0;
            for(int i=0;i<va_count;i++){
                TVal v; SET_VAL(&v,&args[va_start+i]);
                tab_rawset_i(L,va_tab,i+1,&v);
            }
            /* Store count */
            TVal cnt; SET_NUM(&cnt,(double)va_count);
            tab_rawset_s(L,va_tab,s_newz(L,"n"),&cnt);
            TVal va_val; SET_TAB(&va_val,va_tab);
            env_set(env,s_newz(L,"..."),&va_val);
        }
        /* Execute body */
        TVal ret_vals[256];
        int nret_actual=0;
        int sig=eval_block(L,cl->body,env,ret_vals,&nret_actual);
        (void)sig;
        /* Store results */
        if(nret>=0){
            for(int i=0;i<nret&&i<nret_actual;i++) SET_VAL(&ret[i],&ret_vals[i]);
            for(int i=nret_actual;i<nret;i++) SET_NIL(&ret[i]);
        }else{
            /* MULTRET */
            for(int i=0;i<nret_actual;i++) SET_VAL(&ret[i],&ret_vals[i]);
        }
        /* Store actual count for MULTRET callers */
        if(nret==LUA_MULTRET&&nret_actual<256) {
            /* signal nret_actual via L's state */
            L->coro_nresults=nret_actual;
        }
        L->ncC--;
    }else{
        luaG_runerror(L,"attempt to call invalid function");
    }
}

/* Call with stack-based API (for C functions) */
static int vm_pcall_raw(lua_State*L,TVal*func,int nres) {
    /* Not used in AST interpreter */
    return 0;
