        while(srclen>0&&src[0]!='\n'){src++;srclen--;}
    }

    /* Parse */
    LErr err; err.prev=L->err; err.st=LUA_OK;
    L->err=&err;
    Node*ast=NULL;
    int r=setjmp(err.jb);
    if(r==0){
        ast=lua_parse(L,src,srclen,sname);
    }
    L->err=err.prev;
    LFREE(buf);

    if(r!=0){
        /* Parse error - error message on stack */
        return LUA_ERRSYNTAX;
    }

    /* Create a closure that executes the AST */
    Node*fn_node=node_new(N_FUNC,0);
    nl_init(&fn_node->func.params);
    fn_node->func.has_va=1; /* main chunk is vararg */
    fn_node->func.body=ast;
    fn_node->func.name=NULL;
    fn_node->func.is_method=0;

    /* Create the environment */
    Env*env=env_new(L,NULL); /* Top-level env */

    Func*fn=lclosure_new_ast(L,fn_node,env);
    LuaClosure*cl=(LuaClosure*)fn;
    cl->src=s_newz(L,sname);

    CHK_STK(L,1); SET_FUNC(L->top,fn); L->top++;
    return LUA_OK;
}

