typedef struct StrReader { const char*s; size_t len; int done; } StrReader;
static const char*str_reader(lua_State*L,void*data,size_t*sz){
    StrReader*sr=(StrReader*)data;
    if(sr->done){*sz=0;return NULL;}
    sr->done=1; *sz=sr->len; return sr->s;
}
