        CHK_STK(L,1); 
        if(L->top>L->stk) SET_VAL(L->top,L->top); /* already there? */
        /* The error was stored during throw */
        /* Actually it's on the stack already from luaG_runerror */
        /* But we reset top... need to save it */
        SET_VAL(L->top,&ret[0]); L->top++;
    }else{
        CHK_STK(L,nr+1);
        for(int i=0;i<nr;i++){ SET_VAL(L->top,&ret[i]); L->top++; }
