int lua_load(lua_State*L,lua_Reader reader,void*data,const char*chunkname){
    /* Read all data */
    char*buf=NULL; size_t total=0;
    while(1){
        size_t sz;
        const char*piece=reader(L,data,&sz);
        if(!piece||sz==0) break;
        buf=(char*)lm_realloc(buf,total+sz+1);
        memcpy(buf+total,piece,sz);
        total+=sz;
    }
    if(buf) buf[total]='\0';
    else buf=lm_alloc(1), buf[0]='\0';

    /* Check for LuaJIT bytecode header */
    if(total>=3&&buf[0]=='\x1b'&&buf[1]=='L'&&buf[2]=='J'){
        /* This is LuaJIT bytecode - we need to load it */
        /* For now, we can't execute foreign bytecode */
        /* Check if it's our own format */
        /* Our format: \x1bLJ\x02 followed by our data */
        /* TODO: implement bytecode loading */
        LFREE(buf);
        lua_pushstring(L,"cannot load LuaJIT bytecode");
        return LUA_ERRSYNTAX;
    }
    /* Check for Lua 5.1 standard bytecode \x1bLua */
    if(total>=4&&buf[0]=='\x1b'&&buf[1]=='L'&&buf[2]=='u'&&buf[3]=='a'){
        LFREE(buf);
        lua_pushstring(L,"cannot load Lua 5.1 bytecode");
        return LUA_ERRSYNTAX;
    }

    /* Parse as source */
    /* Set up chunk name */
    const char*sname=chunkname?chunkname:"?";
    /* Strip leading shebang */
    const char*src=buf; size_t srclen=total;
    if(srclen>=2&&src[0]=='#'&&src[1]=='!'){
        while(srclen>0&&src[0]!='\n'){src++;srclen--;}
    }

    /* Parse */
    LErr err; err.prev=L->err; err.st=LUA_OK;
    L->err=&err;
    Node*ast=NULL;
    int r=setjmp(err.jb);
    if(r==0){
        ast=lua_parse(L,src,srclen,sname);
    }
    L->err=err.prev;
    LFREE(buf);

    if(r!=0){
        /* Parse error - error message on stack */
        return LUA_ERRSYNTAX;
    }

    /* Create a closure that executes the AST */
    Node*fn_node=node_new(N_FUNC,0);
    nl_init(&fn_node->func.params);
    fn_node->func.has_va=1; /* main chunk is vararg */
    fn_node->func.body=ast;
    fn_node->func.name=NULL;
    fn_node->func.is_method=0;

    /* Create the environment */
    Env*env=env_new(L,NULL); /* Top-level env */

    Func*fn=lclosure_new_ast(L,fn_node,env);
    LuaClosure*cl=(LuaClosure*)fn;
    cl->src=s_newz(L,sname);

    CHK_STK(L,1); SET_FUNC(L->top,fn); L->top++;
    return LUA_OK;
}

