    TVal*k=L->top-2;
    if(IS_TAB(t)) tab_rawset(L,TAB_VAL(t),k,v);
    L->top-=2;
}
void lua_rawseti(lua_State*L,int idx,int n){
    TVal*t=stk_at(L,idx);
