    if(IS_TAB(t)) tab_rawset_i(L,TAB_VAL(t),n,v);
    L->top--;
}
int lua_setmetatable(lua_State*L,int idx){
    TVal*v=stk_at(L,idx);
    TVal*mt_v=L->top-1;
    Tab*mt=IS_NIL(mt_v)?NULL:IS_TAB(mt_v)?TAB_VAL(mt_v):NULL;
    if(IS_TAB(v)) TAB_VAL(v)->mt=mt;
    else if(IS_UD(v)) UD_VAL(v)->mt=mt;
