}
int lua_setfenv(lua_State*L,int idx){
    TVal*v=stk_at(L,idx);
    TVal*env_v=L->top-1;
    if(IS_FUNC(v)&&FUNC_VAL(v)->c.is_c==2){
        LuaClosure*cl=(LuaClosure*)FUNC_VAL(v);
        if(IS_TAB(env_v)){
            /* Update the env - for simplicity update globals */
            /* In proper Lua this would change the function's environment */
            cl->env=env_new(L,NULL);
            /* Copy the table entries into the env */
            Tab*etab=TAB_VAL(env_v);
            TVal k,val;
            SET_NIL(&k);
            while(tab_next(L,etab,&k,&val)>0){
                if(IS_STR(&k)) env_set(cl->env,STR_VAL(&k),&val);
            }
