    L->top--;
    return 1;
}

/* Call functions */
void lua_call(lua_State*L,int nargs,int nresults){
    TVal*func=L->top-nargs-1;
    TVal*args=func+1;
    if(!IS_FUNC(func)){
        /* check __call */
        TVal*mm=get_metamethod(L,func,TM_CALL);
        if(!mm||!IS_FUNC(mm)) luaG_typeerror(L,func,"call");
        /* prepend original func to args */
        /* TODO: handle this properly */
        luaG_typeerror(L,func,"call");
    }
    TVal ret[256];
    eval_call(L,FUNC_VAL(func),args,nargs,ret,nresults==LUA_MULTRET?LUA_MULTRET:nresults);
    int nr=nresults==LUA_MULTRET?L->coro_nresults:nresults;
    L->top=func;
    CHK_STK(L,nr+1);
    for(int i=0;i<nr;i++){ SET_VAL(L->top,&ret[i]); L->top++; }
}

int lua_pcall(lua_State*L,int nargs,int nresults,int errfunc){
    TVal*func=L->top-nargs-1;
    TVal*args=func+1;
    if(!IS_FUNC(func)){
        TVal*mm=get_metamethod(L,func,TM_CALL);
        if(!mm||!IS_FUNC(mm)){
            /* Error */
            TVal err; SET_STR(&err,s_newz(L,"attempt to call a non-function value"));
            L->top=func;
            CHK_STK(L,1); SET_VAL(L->top,&err); L->top++;
            return LUA_ERRRUN;
        }
    }
    TVal ret[256];
    int r=lua_pcall_impl(L,IS_FUNC(func)?FUNC_VAL(func):NULL,args,nargs,ret,
                         nresults==LUA_MULTRET?LUA_MULTRET:nresults);
    int nr=nresults==LUA_MULTRET?L->coro_nresults:nresults;
    L->top=func;
    if(r!=LUA_OK){
        /* Push error */
        CHK_STK(L,1); 
        if(L->top>L->stk) SET_VAL(L->top,L->top); /* already there? */
        /* The error was stored during throw */
        /* Actually it's on the stack already from luaG_runerror */
        /* But we reset top... need to save it */
        SET_VAL(L->top,&ret[0]); L->top++;
    }else{
        CHK_STK(L,nr+1);
        for(int i=0;i<nr;i++){ SET_VAL(L->top,&ret[i]); L->top++; }
    }
    return r;
}

int lua_next(lua_State*L,int idx){
    TVal*t=stk_at(L,idx);
    if(!IS_TAB(t)) luaG_runerror(L,"table expected");
    TVal*k=L->top-1;
    TVal v;
    int r=tab_next(L,TAB_VAL(t),k,&v);
    if(r<=0){
        if(r<0) luaG_runerror(L,"invalid key to 'next'");
        L->top--; return 0;
    }
    CHK_STK(L,1); SET_VAL(L->top,&v); L->top++;
    return 1;
}

void lua_concat(lua_State*L,int n){
    if(n==0){ CHK_STK(L,1); SET_STR(L->top,s_newz(L,"")); L->top++; return; }
    if(n==1) return;
    TVal result; SET_VAL(&result,L->top-n);
    for(int i=1;i<n;i++){
        TVal tmp; do_concat(L,&result,L->top-n+i,&tmp);
        SET_VAL(&result,&tmp);
    }
    L->top-=n; CHK_STK(L,1); SET_VAL(L->top,&result); L->top++;
}

int lua_error(lua_State*L){
    /* The error value is on top of stack */
    /* But we don't pop it - it stays for the error handler */
    L_throw(L,LUA_ERRRUN);
    return 0; /* unreachable */
}

int lua_load(lua_State*L,lua_Reader reader,void*data,const char*chunkname){
    /* Read all data */
    char*buf=NULL; size_t total=0;
    while(1){
        size_t sz;
        const char*piece=reader(L,data,&sz);
        if(!piece||sz==0) break;
        buf=(char*)lm_realloc(buf,total+sz+1);
        memcpy(buf+total,piece,sz);
        total+=sz;
    }
    if(buf) buf[total]='\0';
    else buf=lm_alloc(1), buf[0]='\0';

    /* Check for LuaJIT bytecode header */
    if(total>=3&&buf[0]=='\x1b'&&buf[1]=='L'&&buf[2]=='J'){
        /* This is LuaJIT bytecode - we need to load it */
        /* For now, we can't execute foreign bytecode */
        /* Check if it's our own format */
        /* Our format: \x1bLJ\x02 followed by our data */
        /* TODO: implement bytecode loading */
        LFREE(buf);
        lua_pushstring(L,"cannot load LuaJIT bytecode");
        return LUA_ERRSYNTAX;
    }
    /* Check for Lua 5.1 standard bytecode \x1bLua */
    if(total>=4&&buf[0]=='\x1b'&&buf[1]=='L'&&buf[2]=='u'&&buf[3]=='a'){
        LFREE(buf);
        lua_pushstring(L,"cannot load Lua 5.1 bytecode");
        return LUA_ERRSYNTAX;
    }

    /* Parse as source */
    /* Set up chunk name */
    const char*sname=chunkname?chunkname:"?";
    /* Strip leading shebang */
    const char*src=buf; size_t srclen=total;
    if(srclen>=2&&src[0]=='#'&&src[1]=='!'){
        while(srclen>0&&src[0]!='\n'){src++;srclen--;}
    }

    /* Parse */
    LErr err; err.prev=L->err; err.st=LUA_OK;
    L->err=&err;
    Node*ast=NULL;
    int r=setjmp(err.jb);
    if(r==0){
        ast=lua_parse(L,src,srclen,sname);
    }
    L->err=err.prev;
    LFREE(buf);

    if(r!=0){
        /* Parse error - error message on stack */
        return LUA_ERRSYNTAX;
    }

    /* Create a closure that executes the AST */
    Node*fn_node=node_new(N_FUNC,0);
    nl_init(&fn_node->func.params);
    fn_node->func.has_va=1; /* main chunk is vararg */
    fn_node->func.body=ast;
    fn_node->func.name=NULL;
    fn_node->func.is_method=0;

    /* Create the environment */
    Env*env=env_new(L,NULL); /* Top-level env */

    Func*fn=lclosure_new_ast(L,fn_node,env);
    LuaClosure*cl=(LuaClosure*)fn;
    cl->src=s_newz(L,sname);

    CHK_STK(L,1); SET_FUNC(L->top,fn); L->top++;
    return LUA_OK;
}

/* String-based load */
typedef struct StrReader { const char*s; size_t len; int done; } StrReader;
static const char*str_reader(lua_State*L,void*data,size_t*sz){
    StrReader*sr=(StrReader*)data;
    if(sr->done){*sz=0;return NULL;}
    sr->done=1; *sz=sr->len; return sr->s;
}
static int luaL_loadbuffer(lua_State*L,const char*s,size_t len,const char*name){
    StrReader sr={s,len,0};
    return lua_load(L,str_reader,&sr,name);
}
static int luaL_loadstring(lua_State*L,const char*s){
    return luaL_loadbuffer(L,s,strlen(s),s);
}
static int luaL_loadfile(lua_State*L,const char*fname){
    FILE*f;
    if(!fname){ f=stdin; fname="stdin"; }
    else{
        f=fopen(fname,"rb");
        if(!f){
            lua_pushfstring(L,"cannot open %s: %s",fname,strerror(errno));
            return LUA_ERRRUN;
        }
    }
    /* Read file */
    char*buf=NULL; size_t total=0;
    char tmp[4096];
    while(!feof(f)){
        size_t nr=fread(tmp,1,sizeof(tmp),f);
        if(nr>0){
            buf=(char*)lm_realloc(buf,total+nr+1);
            memcpy(buf+total,tmp,nr);
            total+=nr;
        }
    }
    if(fname!=NULL&&fname[0]!='s') fclose(f);
    if(!buf){buf=(char*)lm_alloc(1);total=0;}
    buf[total]='\0';

    char chunkname[256];
    snprintf(chunkname,sizeof(chunkname),"@%s",fname);

    StrReader sr={buf,total,0};
    int r=lua_load(L,str_reader,&sr,chunkname);
    LFREE(buf);
    return r;
}

