/* ============================================================ */
/* LUA STATE INITIALIZATION */
/* ============================================================ */
static lua_State*lua_newstate(void){
    GState*g=(GState*)lm_alloc(sizeof(GState));
    memset(g,0,sizeof(*g));
    g->strt.sz=STRT_INIT;
    g->strt.h=(Str**)lm_alloc(sizeof(Str*)*STRT_INIT);
    memset(g->strt.h,0,sizeof(Str*)*STRT_INIT);
    g->allgc=NULL; g->reg=NULL;
    g->open_upvals=NULL; g->cfn_id=1;

    lua_State*L=(lua_State*)lm_alloc(sizeof(lua_State));
    memset(L,0,sizeof(*L));
    L->type=LUA_TTHREAD; L->gc_mark=0;
    L->status=LUA_OK; L->g=g;
    g->main=L;

    stk_init(L);
    ci_init(L);
    L->ncC=0;
    L->err=NULL; L->errfn=0;
    L->open_uv=NULL; L->gclist=NULL;
    L->coro_nresults=0;
    L->coro_status=2; /* running */
    L->resumer=NULL;

    /* Create globals table */
    g->reg=tab_new(L);
    Tab*globals=tab_new(L);
    SET_TAB(&L->globals,globals);
    SET_TAB(&L->env,globals);

    /* Registry[1] = globals, Registry[2] = main thread */
    TVal gv; SET_TAB(&gv,globals);
    tab_rawset_i(L,g->reg,LUA_RIDX_GLOBALS,&gv);

    return L;
}

#define LUA_RIDX_GLOBALS 1
#define LUA_RIDX_MAINTHREAD 2

/* ============================================================ */
/* PROTECTED CALL */
/* ============================================================ */
typedef struct {
    Func*fn;
    TVal*args;
    int nargs;
    TVal*ret;
    int nret;
    int actual_ret;
} CallData;

static void do_call(lua_State*L,void*cd_void){
    CallData*cd=(CallData*)cd_void;
    eval_call(L,cd->fn,cd->args,cd->nargs,cd->ret,cd->nret);
    if(cd->nret==LUA_MULTRET) cd->actual_ret=L->coro_nresults;
    else cd->actual_ret=cd->nret;
}

static int lua_pcall_impl(lua_State*L,Func*fn,TVal*args,int nargs,TVal*ret,int nret){
    LErr err; err.prev=L->err; err.st=LUA_OK;
    L->err=&err;
    int r=setjmp(err.jb);
    if(r==0){
        CallData cd={fn,args,nargs,ret,nret,0};
        do_call(L,&cd);
        if(nret==LUA_MULTRET) nret=cd.actual_ret;
    }else{
        /* Error occurred - top of stack has error message */
        if(ret&&nret>0){
            if(L->top>L->stk){
                SET_VAL(&ret[0],L->top-1);
            }else SET_NIL(&ret[0]);
        }
        /* Clean up stack */
        L->err=err.prev;
        return err.st;
    }
    L->err=err.prev;
    return LUA_OK;
}

