/* LUA C API IMPLEMENTATION */
/* ============================================================ */

/* Stack index to TVal */
static TVal*getidx(lua_State*L,int idx){
    if(idx>0) return L->base+idx-1;
    else if(idx<0&&idx>LUA_REGISTRYINDEX) return L->top+idx;
    else if(idx==LUA_REGISTRYINDEX) return (TVal*)G(L)->reg; /* hack */
    else if(idx==LUA_GLOBALSINDEX) return &L->globals;
    else if(idx==LUA_ENVIRONINDEX) return &L->env;
    else{
        int uv_idx=LUA_GLOBALSINDEX-idx;
        /* Get upvalue from current C closure */
        TVal*func=L->ci->func;
        if(func&&IS_FUNC(func)){
            Func*fn=FUNC_VAL(func);
            if(fn->c.is_c==1&&uv_idx>=1&&uv_idx<=fn->c.nup)
                return &fn->c.upvals[uv_idx-1];
        }
    }
    return NULL;
}

static TVal*getidx_tab(lua_State*L,int idx){
    if(idx==LUA_GLOBALSINDEX) return &L->globals;
    if(idx==LUA_ENVIRONINDEX) return &L->env;
    if(idx==LUA_REGISTRYINDEX){
        /* Return registry as a TVal */
        static TVal reg_tv;
        SET_TAB(&reg_tv,G(L)->reg);
        return &reg_tv;
    }
    return getidx(L,idx);
}

/* Push/pop helpers */
static void push_tv(lua_State*L,const TVal*v){
    CHK_STK(L,1);
    SET_VAL(L->top,v); L->top++;
}

/* For C function calls, L->base and L->ci are set up */
/* Access stack relative to base */
static TVal*stk_at(lua_State*L,int idx){
    if(idx>0) return L->base+idx-1;
    else if(idx<0&&idx>LUA_REGISTRYINDEX) return L->top+idx;
    else return getidx_tab(L,idx);
}

/* C API functions */
int lua_gettop(lua_State*L){return(int)(L->top-L->base);}
void lua_settop(lua_State*L,int n){
    if(n>=0){
        while(L->top<L->base+n){ SET_NIL(L->top); L->top++; }
        L->top=L->base+n;
    }else{
        L->top=L->top+(n+1);
        if(L->top<L->base) L->top=L->base;
    }
}
void lua_pushvalue(lua_State*L,int idx){ TVal*v=stk_at(L,idx); push_tv(L,v); }
void lua_remove(lua_State*L,int idx){
    TVal*v=stk_at(L,idx);
    memmove(v,v+1,sizeof(TVal)*(L->top-v-1));
    L->top--;
}
void lua_insert(lua_State*L,int idx){
    TVal*v=stk_at(L,idx);
    memmove(v+1,v,sizeof(TVal)*(L->top-v));
    SET_NIL(v); /* will be filled in */
    /* Caller must set the value */
}
