    TVal*args=L->base+1;
    int nargs=n-1;

    if(!IS_FUNC(func)){
        /* Check __call */
        TVal*mm=get_metamethod(L,func,TM_CALL);
        if(!mm){
            lua_pushboolean(L,0);
            char buf[64]; lua_pushfstring(L,"attempt to call a %s value",val_tostr(L,func,buf,sizeof(buf)));
            return 2;
        }
    }

    Func*fn=IS_FUNC(func)?FUNC_VAL(func):NULL;
    TVal ret[256];
    int r=lua_pcall_impl(L,fn,args,nargs,ret,LUA_MULTRET);
    int nr=L->coro_nresults;

    /* Reset stack to func position + 1 */
    L->top=L->base;

    if(r==LUA_OK){
        CHK_STK(L,nr+2);
        SET_BOOL(L->top,1); L->top++;
        for(int i=0;i<nr;i++){ SET_VAL(L->top,&ret[i]); L->top++; }
        return 1+nr;
    }else{
        CHK_STK(L,3);
        SET_BOOL(L->top,0); L->top++;
        /* Error message from ret[0] or from stack */
        if(ret[0].type!=LUA_TNIL) SET_VAL(L->top,&ret[0]);
        else if(L->top>L->base) SET_VAL(L->top,L->top);
        else SET_STR(L->top,s_newz(L,"error"));
