static int lua_xpcall_f(lua_State*L){
    int n=lua_gettop(L);
    if(n<2){ lua_pushboolean(L,0); lua_pushstring(L,"bad argument"); return 2; }
    TVal fn_v; SET_VAL(&fn_v,stk_at(L,1));
    TVal handler_v; SET_VAL(&handler_v,stk_at(L,2));

    /* Additional args */
    int nargs=n-2;
    TVal*args=L->base+2;

    Func*fn=IS_FUNC(&fn_v)?FUNC_VAL(&fn_v):NULL;

    /* Save handler */
    TVal ret[256];
    LErr err; err.prev=L->err; err.st=LUA_OK;
    L->err=&err;
    int r=setjmp(err.jb);
    if(r==0){
        if(fn) eval_call(L,fn,args,nargs,ret,LUA_MULTRET);
        else luaG_typeerror(L,&fn_v,"call");
    }else{
        /* Call handler */
        L->err=err.prev;
        TVal err_val;
        if(L->top>L->base) SET_VAL(&err_val,L->top-1);
        else SET_STR(&err_val,s_newz(L,"error"));

        /* Reset stack */
        L->top=L->base;

        if(IS_FUNC(&handler_v)){
            TVal hargs[1]; SET_VAL(&hargs[0],&err_val);
            TVal hret[1]; SET_NIL(&hret[0]);
            eval_call(L,FUNC_VAL(&handler_v),hargs,1,hret,1);
            SET_BOOL(L->top,0); L->top++;
            SET_VAL(L->top,&hret[0]); L->top++;
        }else{
            SET_BOOL(L->top,0); L->top++;
            SET_VAL(L->top,&err_val); L->top++;
        }
        return 2;
    }
    L->err=err.prev;
    int nr=L->coro_nresults;
    L->top=L->base;
    SET_BOOL(L->top,1); L->top++;
    for(int i=0;i<nr;i++){ SET_VAL(L->top,&ret[i]); L->top++; }
    return 1+nr;
}

