static int lua_pcall_f(lua_State*L){
    int n=lua_gettop(L);
    if(n<1){ lua_pushboolean(L,0); lua_pushstring(L,"value expected"); return 2; }
    TVal*func=stk_at(L,1);
    TVal*args=L->base+1;
    int nargs=n-1;

    if(!IS_FUNC(func)){
        /* Check __call */
        TVal*mm=get_metamethod(L,func,TM_CALL);
        if(!mm){
            lua_pushboolean(L,0);
            char buf[64]; lua_pushfstring(L,"attempt to call a %s value",val_tostr(L,func,buf,sizeof(buf)));
            return 2;
