static const char*matchbalance(MatchState*ms,const char*s,const char*p){
    if(p>=ms->src_end-1) return NULL;
    if(*s!=*p) return NULL;
    int b=*p, e=*(p+1), cont=1;
    while(++s<ms->src_end){
