static int str_match(lua_State*L){ return str_find_aux(L,0); }

static int str_gmatch_iter(lua_State*L){
    size_t ls;
    const char*s=lua_tolstring(L,lua_upvalueindex(1),&ls);
    const char*p=lua_tostring(L,lua_upvalueindex(2));
    int pos=(int)lua_tonumber(L,lua_upvalueindex(3));

    MatchState ms;
    ms.src_init=s; ms.src_end=s+ls; ms.L=L; ms.level=0;

    while(pos<=(int)ls){
        ms.level=0;
        const char*s2=s+pos;
        const char*res=match(&ms,s2,p);
        if(res){
            int newpos=(int)(res-s);
            if(res==s2) newpos++;
            lua_pushnumber(L,(double)newpos);
            lua_replace(L,lua_upvalueindex(3));
            push_captures(&ms,L,s2,res);
            return ms.level==0?1:ms.level;
        }
        pos++;
    }
    return 0;
}

