/* ===== STRING LIBRARY ===== */
/* Pattern matching */
#define CAP_UNFINISHED (-1)
#define CAP_POSITION   (-2)
#define MAXCAPS 32

typedef struct MatchState {
    const char*src_init;
    const char*src_end;
    lua_State*L;
    int level;
    struct { const char*init; ptrdiff_t len; } capture[MAXCAPS];
} MatchState;

static int check_capture(MatchState*ms,int l){
    l-='1';
    if(l<0||l>=ms->level||ms->capture[l].len==CAP_UNFINISHED)
        luaG_runerror(ms->L,"invalid back reference %%%d",l+1);
    return l;
}

static int capture_to_close(MatchState*ms){
    int l=ms->level;
    for(l--;l>=0;l--) if(ms->capture[l].len==CAP_UNFINISHED) return l;
    luaG_runerror(ms->L,"invalid pattern capture");
    return -1;
}

static const char*classend(MatchState*ms,const char*p){
    switch(*p++){
    case '\0': luaG_runerror(ms->L,"malformed pattern (ends with '%')"); break;
    case '%': if(*p=='\0') luaG_runerror(ms->L,"malformed pattern"); p++; break;
    case '[': if(*p=='^') p++; do{if(*p=='\0') luaG_runerror(ms->L,"malformed pattern");} while(*p++!=']'); break;
    }
    return p;
}

static int singlematch(MatchState*ms,const char*s,const char*p,const char*ep){
    if(s>=ms->src_end) return 0;
    unsigned char c=(unsigned char)*s;
    switch(*p){
    case '.': return 1;
    case '%':
        switch(p[1]){
        case 'a': return isalpha(c)?1:0;
        case 'A': return !isalpha(c)?1:0;
        case 'd': return isdigit(c)?1:0;
        case 'D': return !isdigit(c)?1:0;
        case 'l': return islower(c)?1:0;
        case 'L': return !islower(c)?1:0;
        case 'u': return isupper(c)?1:0;
        case 'U': return !isupper(c)?1:0;
        case 's': return isspace(c)?1:0;
        case 'S': return !isspace(c)?1:0;
        case 'w': return isalnum(c)?1:0;
        case 'W': return !isalnum(c)?1:0;
        case 'p': return ispunct(c)?1:0;
        case 'P': return !ispunct(c)?1:0;
        case 'c': return iscntrl(c)?1:0;
        case 'C': return !iscntrl(c)?1:0;
        case 'x': return isxdigit(c)?1:0;
        case 'X': return !isxdigit(c)?1:0;
        default: return c==(unsigned char)p[1]?1:0;
        }
    case '[': {
        int neg=0; const char*pp=p+1;
        if(*pp=='^'){neg=1;pp++;}
        int found=0;
        while(*pp!=']'){
            if(*(pp+1)=='-'&&*(pp+2)!=']'){
                if(c>=(unsigned char)*pp&&c<=(unsigned char)*(pp+2)) found=1;
                pp+=3;
            }else if(*pp=='%'){
                pp++; /* TODO: handle class */
                switch(*pp){
                case 'a': if(isalpha(c)) found=1; break;
                case 'd': if(isdigit(c)) found=1; break;
                case 'l': if(islower(c)) found=1; break;
                case 'u': if(isupper(c)) found=1; break;
                case 's': if(isspace(c)) found=1; break;
                case 'w': if(isalnum(c)) found=1; break;
                case 'p': if(ispunct(c)) found=1; break;
                case 'x': if(isxdigit(c)) found=1; break;
                default: if(c==(unsigned char)*pp) found=1; break;
                }
                pp++;
            }else{
                if(c==(unsigned char)*pp) found=1;
                pp++;
            }
        }
        return (found^neg)?1:0;
    }
    default: return c==(unsigned char)*p?1:0;
    }
}

static const char*match(MatchState*ms,const char*s,const char*p);

static const char*matchbalance(MatchState*ms,const char*s,const char*p){
    if(p>=ms->src_end-1) return NULL;
    if(*s!=*p) return NULL;
    int b=*p, e=*(p+1), cont=1;
    while(++s<ms->src_end){
        if(*s==e){if(--cont==0) return s+1;}
        else if(*s==b) cont++;
    }
    return NULL;
}

static const char*max_expand(MatchState*ms,const char*s,const char*p,const char*ep){
    int i=0;
    while(s+i<ms->src_end&&singlematch(ms,s+i,p,ep)) i++;
    while(i>=0){
        const char*res=match(ms,s+i,ep);
        if(res) return res;
        i--;
    }
