            if(singlematch(ms,&prev,p,ep)||!singlematch(ms,s,p,ep)) return NULL;
            p=ep; goto init;
        }
        default: {
            int l; 
            if(isdigit((unsigned char)*(p+1))){
                l=check_capture(ms,*(p+1));
                size_t len=ms->capture[l].len;
                if((size_t)(ms->src_end-s)>=len&&!memcmp(ms->capture[l].init,s,len)){
                    s+=len; p+=2; goto init;
                }
                return NULL;
            }
            goto dflt;
        }
        }
    }
    default: dflt: {
        const char*ep=classend(ms,p);
        int m=singlematch(ms,s,p,ep);
        switch(*ep){
        case '?': {
            const char*res;
            if(m&&(res=match(ms,s+1,ep+1))) return res;
            p=ep+1; goto init;
        }
        case '*': return max_expand(ms,s,p,ep);
        case '+': return m?max_expand(ms,s+1,p,ep):NULL;
        case '-': return min_expand(ms,s,p,ep);
