            prev=s==ms->src_init?'\0':*(s-1);
            if(singlematch(ms,&prev,p,ep)||!singlematch(ms,s,p,ep)) return NULL;
            p=ep; goto init;
        }
        default: {
            int l; 
            if(isdigit((unsigned char)*(p+1))){
                l=check_capture(ms,*(p+1));
                size_t len=ms->capture[l].len;
                if((size_t)(ms->src_end-s)>=len&&!memcmp(ms->capture[l].init,s,len)){
                    s+=len; p+=2; goto init;
                }
                return NULL;
            }
            goto dflt;
        }
        }
    }
    default: dflt: {
        const char*ep=classend(ms,p);
        int m=singlematch(ms,s,p,ep);
        switch(*ep){
        case '?': {
            const char*res;
            if(m&&(res=match(ms,s+1,ep+1))) return res;
            p=ep+1; goto init;
        }
        case '*': return max_expand(ms,s,p,ep);
        case '+': return m?max_expand(ms,s+1,p,ep):NULL;
        case '-': return min_expand(ms,s,p,ep);
        default:
            if(!m) return NULL;
            s++; p=ep; goto init;
        }
    }
    }
}

static void push_captures(MatchState*ms,lua_State*L,const char*s,const char*e){
    int nlevels=(ms->level==0&&s)?1:ms->level;
    for(int i=0;i<nlevels;i++){
        if(ms->capture[i].len==CAP_POSITION){
            lua_pushnumber(L,(double)(ms->capture[i].init-ms->src_init+1));
        }else if(ms->capture[i].len==CAP_UNFINISHED){
            luaG_runerror(L,"unfinished capture");
        }else{
            lua_pushlstring(L,ms->capture[i].init,(size_t)ms->capture[i].len);
        }
    }
    if(nlevels==0&&s) lua_pushlstring(L,s,(size_t)(e-s));
}

static int str_find_aux(lua_State*L,int find){
    size_t ls,lp;
    const char*s=check_str(L,1); ls=STR_VAL(stk_at(L,1))->len;
    const char*p=check_str(L,2); lp=STR_VAL(stk_at(L,2))->len;
    int init=opt_int(L,3,1);
    int plain=lua_toboolean(L,4);

    if(init<0) init=(int)ls+init+1;
    if(init<1) init=1;
    if(init>(int)ls+1){ lua_pushnil(L); return 1; }

    const char*s1=s+init-1;
    if(find&&plain){
        /* Plain search */
        const char*found=(const char*)memmem(s1,ls-(init-1),p,lp);
        if(!found){lua_pushnil(L);return 1;}
        lua_pushnumber(L,(double)(found-s+1));
        lua_pushnumber(L,(double)(found-s+lp));
        return 2;
    }

    MatchState ms;
    ms.src_init=s; ms.src_end=s+ls; ms.L=L; ms.level=0;

    int anchor=0;
    if(*p=='^'){anchor=1;p++;}

    const char*s2=s1;
    do{
        ms.level=0;
        const char*res=match(&ms,s2,p);
        if(res){
            if(find){
                lua_pushnumber(L,(double)(s2-s+1));
                lua_pushnumber(L,(double)(res-s));
                push_captures(&ms,L,s2,res);
                return 2+ms.level+(ms.level==0?1:0);
            }else{
                push_captures(&ms,L,s2,res);
                return ms.level==0?1:ms.level;
            }
        }
    }while(s2++<ms.src_end&&!anchor);

    lua_pushnil(L);
    return 1;
}

