                    if(rlen+(e-src)>=rcap){rcap=(rlen+(e-src)+64)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
                    memcpy(rbuf+rlen,src,(size_t)(e-src)); rlen+=e-src;
