    if(p>=ms->src_end-1) return NULL;
    if(*s!=*p) return NULL;
    int b=*p, e=*(p+1), cont=1;
    while(++s<ms->src_end){
        if(*s==e){if(--cont==0) return s+1;}
        else if(*s==b) cont++;
    }
    return NULL;
}

static const char*max_expand(MatchState*ms,const char*s,const char*p,const char*ep){
    int i=0;
    while(s+i<ms->src_end&&singlematch(ms,s+i,p,ep)) i++;
    while(i>=0){
        const char*res=match(ms,s+i,ep);
        if(res) return res;
        i--;
    }
    return NULL;
}

static const char*min_expand(MatchState*ms,const char*s,const char*p,const char*ep){
    while(1){
        const char*res=match(ms,s,ep);
        if(res) return res;
        if(s<ms->src_end&&singlematch(ms,s,p,ep)) s++;
        else return NULL;
    }
}

static const char*match(MatchState*ms,const char*s,const char*p){
    if(!p) return s;
init:
    if(p>=ms->src_end+1) return s; /* ?? */
    switch(*p){
    case '(': {
        if(*(p+1)==')'){ /* position capture */
            int l=ms->level;
            ms->capture[l].init=s;
            ms->capture[l].len=CAP_POSITION;
            ms->level=l+1;
            const char*res=match(ms,s,p+2);
            if(!res) ms->level--;
            return res;
        }else{
            int l=ms->level;
            ms->capture[l].init=s;
            ms->capture[l].len=CAP_UNFINISHED;
            ms->level=l+1;
            const char*res=match(ms,s,p+1);
            if(!res) ms->level--;
            return res;
        }
    }
    case ')': {
        int l=capture_to_close(ms);
        ms->capture[l].len=s-ms->capture[l].init;
        const char*res=match(ms,s,p+1);
        if(!res) ms->capture[l].len=CAP_UNFINISHED;
        return res;
    }
    case '$':
        if(*(p+1)=='\0') return s==ms->src_end?s:NULL;
        goto dflt;
    case '%': {
        switch(*(p+1)){
        case 'b': {
            s=matchbalance(ms,s,p+2);
            if(!s) return NULL;
            p+=4; goto init;
        }
        case 'f': { /* frontier */
            const char*ep; char prev;
            p+=2; if(*p!='[') luaG_runerror(ms->L,"missing '[' after '%%f' in pattern");
            ep=classend(ms,p);
            prev=s==ms->src_init?'\0':*(s-1);
            if(singlematch(ms,&prev,p,ep)||!singlematch(ms,s,p,ep)) return NULL;
            p=ep; goto init;
        }
        default: {
            int l; 
            if(isdigit((unsigned char)*(p+1))){
                l=check_capture(ms,*(p+1));
                size_t len=ms->capture[l].len;
                if((size_t)(ms->src_end-s)>=len&&!memcmp(ms->capture[l].init,s,len)){
                    s+=len; p+=2; goto init;
                }
                return NULL;
            }
            goto dflt;
        }
        }
    }
    default: dflt: {
        const char*ep=classend(ms,p);
        int m=singlematch(ms,s,p,ep);
        switch(*ep){
        case '?': {
            const char*res;
            if(m&&(res=match(ms,s+1,ep+1))) return res;
            p=ep+1; goto init;
        }
        case '*': return max_expand(ms,s,p,ep);
        case '+': return m?max_expand(ms,s+1,p,ep):NULL;
        case '-': return min_expand(ms,s,p,ep);
        default:
            if(!m) return NULL;
            s++; p=ep; goto init;
        }
    }
    }
}

static void push_captures(MatchState*ms,lua_State*L,const char*s,const char*e){
    int nlevels=(ms->level==0&&s)?1:ms->level;
    for(int i=0;i<nlevels;i++){
        if(ms->capture[i].len==CAP_POSITION){
            lua_pushnumber(L,(double)(ms->capture[i].init-ms->src_init+1));
        }else if(ms->capture[i].len==CAP_UNFINISHED){
            luaG_runerror(L,"unfinished capture");
        }else{
            lua_pushlstring(L,ms->capture[i].init,(size_t)ms->capture[i].len);
        }
    }
    if(nlevels==0&&s) lua_pushlstring(L,s,(size_t)(e-s));
}

static int str_find_aux(lua_State*L,int find){
    size_t ls,lp;
    const char*s=check_str(L,1); ls=STR_VAL(stk_at(L,1))->len;
    const char*p=check_str(L,2); lp=STR_VAL(stk_at(L,2))->len;
    int init=opt_int(L,3,1);
    int plain=lua_toboolean(L,4);

    if(init<0) init=(int)ls+init+1;
    if(init<1) init=1;
    if(init>(int)ls+1){ lua_pushnil(L); return 1; }

    const char*s1=s+init-1;
    if(find&&plain){
        /* Plain search */
        const char*found=(const char*)memmem(s1,ls-(init-1),p,lp);
        if(!found){lua_pushnil(L);return 1;}
        lua_pushnumber(L,(double)(found-s+1));
        lua_pushnumber(L,(double)(found-s+lp));
        return 2;
    }

    MatchState ms;
    ms.src_init=s; ms.src_end=s+ls; ms.L=L; ms.level=0;

    int anchor=0;
    if(*p=='^'){anchor=1;p++;}

    const char*s2=s1;
    do{
        ms.level=0;
        const char*res=match(&ms,s2,p);
        if(res){
            if(find){
                lua_pushnumber(L,(double)(s2-s+1));
                lua_pushnumber(L,(double)(res-s));
                push_captures(&ms,L,s2,res);
                return 2+ms.level+(ms.level==0?1:0);
            }else{
                push_captures(&ms,L,s2,res);
                return ms.level==0?1:ms.level;
            }
        }
    }while(s2++<ms.src_end&&!anchor);

    lua_pushnil(L);
    return 1;
}

static int str_find(lua_State*L){ return str_find_aux(L,1); }
static int str_match(lua_State*L){ return str_find_aux(L,0); }

static int str_gmatch_iter(lua_State*L){
    size_t ls;
    const char*s=lua_tolstring(L,lua_upvalueindex(1),&ls);
    const char*p=lua_tostring(L,lua_upvalueindex(2));
    int pos=(int)lua_tonumber(L,lua_upvalueindex(3));

    MatchState ms;
    ms.src_init=s; ms.src_end=s+ls; ms.L=L; ms.level=0;

    while(pos<=(int)ls){
        ms.level=0;
        const char*s2=s+pos;
        const char*res=match(&ms,s2,p);
        if(res){
            int newpos=(int)(res-s);
            if(res==s2) newpos++;
            lua_pushnumber(L,(double)newpos);
            lua_replace(L,lua_upvalueindex(3));
            push_captures(&ms,L,s2,res);
            return ms.level==0?1:ms.level;
        }
        pos++;
    }
    return 0;
}

static int str_gmatch(lua_State*L){
    check_str(L,1);
    check_str(L,2);
    lua_pushvalue(L,1);
    lua_pushvalue(L,2);
    lua_pushnumber(L,0);
    lua_pushcclosure(L,str_gmatch_iter,3);
    return 1;
}

static int str_gsub(lua_State*L){
    size_t ls,lp;
    const char*s=check_str(L,1); ls=STR_VAL(stk_at(L,1))->len;
    const char*p=check_str(L,2); lp=STR_VAL(stk_at(L,2))->len;
    TVal*repl=stk_at(L,3);
    int maxn=opt_int(L,4,INT_MAX);

    MatchState ms;
    ms.src_init=s; ms.src_end=s+ls; ms.L=L;

    /* Result buffer */
    char*rbuf=NULL; size_t rlen=0, rcap=0;

    int anchor=0;
    const char*pp=p;
    if(*pp=='^'){anchor=1;pp++;}

    const char*src=s;
    int n=0;

    while(n<maxn){
        ms.level=0;
        const char*e=match(&ms,src,pp);
        if(e){
            n++;
            /* Apply replacement */
            if(IS_STR(repl)){
                /* String replacement with %0-%9 */
                const char*r=str_val(STR_VAL(repl));
                while(*r){
                    if(*r=='%'&&*(r+1)){
                        r++;
                        if(*r>='0'&&*r<='9'){
                            int cl=*r-'0';
                            const char*cs; size_t clen;
                            if(cl==0){cs=src;clen=e-src;}
                            else if(cl<=ms.level){
                                cs=ms.capture[cl-1].init;
                                clen=ms.capture[cl-1].len>=0?(size_t)ms.capture[cl-1].len:0;
                            }else{cs="";clen=0;}
                            if(rlen+clen>=rcap){
                                rcap=(rlen+clen+64)*2;
                                rbuf=(char*)lm_realloc(rbuf,rcap);
                            }
                            memcpy(rbuf+rlen,cs,clen); rlen+=clen;
                        }else if(*r=='%'){
                            if(rlen+1>=rcap){rcap=(rlen+64)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
                            rbuf[rlen++]='%';
                        }else{
                            if(rlen+1>=rcap){rcap=(rlen+64)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
                            rbuf[rlen++]='%';
                            if(rlen+1>=rcap){rcap=(rlen+64)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
                            rbuf[rlen++]=*r;
                        }
                    }else{
                        if(rlen+1>=rcap){rcap=(rlen+64)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
                        rbuf[rlen++]=*r;
                    }
                    r++;
                }
            }else if(IS_TAB(repl)){
                /* Table replacement */
                TVal key,val;
                int nlevels=(ms.level==0&&src)?1:ms.level;
                if(nlevels==0||ms.level==0) lua_pushlstring(L,src,(size_t)(e-src));
                else if(ms.capture[0].len==CAP_POSITION) lua_pushnumber(L,(double)(ms.capture[0].init-ms.src_init+1));
                else lua_pushlstring(L,ms.capture[0].init,(size_t)ms.capture[0].len);
                TVal*kv=stk_at(L,lua_gettop(L)); if(!kv)break;
                TVal*tv=tab_rawget(TAB_VAL(repl),kv);
                L->top--;
                const char*rs=(tv&&IS_STR(tv))?str_val(STR_VAL(tv)):NULL;
                if(tv&&TRUTHY(tv)){
                    if(IS_STR(tv)) rs=str_val(STR_VAL(tv));
                    else if(IS_NUM(tv)){char nb[64];val_tostr(L,tv,nb,sizeof(nb));rs=nb;}
                    if(rs){
                        size_t rsl=strlen(rs);
                        if(rlen+rsl>=rcap){rcap=(rlen+rsl+64)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
                        memcpy(rbuf+rlen,rs,rsl); rlen+=rsl;
                    }else{
                        /* no match: keep original */
                        if(rlen+(e-src)>=rcap){rcap=(rlen+(e-src)+64)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
                        memcpy(rbuf+rlen,src,(size_t)(e-src)); rlen+=e-src;
                    }
                }else{
                    /* no replacement: keep original */
                    if(rlen+(e-src)>=rcap){rcap=(rlen+(e-src)+64)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
                    memcpy(rbuf+rlen,src,(size_t)(e-src)); rlen+=e-src;
                }
            }else if(IS_FUNC(repl)){
                /* Function replacement */
                int nlevels=(ms.level==0&&src)?1:ms.level;
                TVal args[MAXCAPS];
                int na=nlevels==0?1:ms.level;
                if(na==0){
                    SET_STR(&args[0],s_new(L,src,(int)(e-src)));
                    na=1;
                }else{
                    for(int i=0;i<ms.level;i++){
                        if(ms.capture[i].len==CAP_POSITION)
                            SET_NUM(&args[i],(double)(ms.capture[i].init-ms.src_init+1));
                        else if(ms.capture[i].len>=0)
                            SET_STR(&args[i],s_new(L,ms.capture[i].init,(int)ms.capture[i].len));
                        else SET_STR(&args[i],s_newz(L,""));
                    }
                }
                TVal res; SET_NIL(&res);
                eval_call(L,FUNC_VAL(repl),args,na,&res,1);
                if(IS_STR(&res)||IS_NUM(&res)){
                    char nb[64];
                    const char*rs=IS_STR(&res)?str_val(STR_VAL(&res)):val_tostr(L,&res,nb,sizeof(nb));
                    size_t rsl=strlen(rs);
                    if(rlen+rsl>=rcap){rcap=(rlen+rsl+64)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
                    memcpy(rbuf+rlen,rs,rsl); rlen+=rsl;
                }else if(IS_NIL(&res)||IS_BOOL(&res)&&!B_VAL(&res)){
                    /* no replacement */
                    if(rlen+(e-src)>=rcap){rcap=(rlen+(e-src)+64)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
                    memcpy(rbuf+rlen,src,(size_t)(e-src)); rlen+=e-src;
                }
            }
        }else{
            /* No match: copy current char */
            if(src>=ms.src_end) break;
            if(rlen+1>=rcap){rcap=(rlen+64)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
            rbuf[rlen++]=*src++;
        }
        if(e){
            if(e==src){
                if(src>=ms.src_end) break;
                if(rlen+1>=rcap){rcap=(rlen+64)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
                rbuf[rlen++]=*src++;
            }else src=e;
        }
        if(anchor) break;
    }

    /* Append rest of string */
    size_t rem=ms.src_end-src;
    if(rlen+rem>=rcap){rcap=(rlen+rem+1)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
    memcpy(rbuf+rlen,src,rem); rlen+=rem;

    lua_pushlstring(L,rbuf?rbuf:"",rlen);
    lua_pushnumber(L,(double)n);
    if(rbuf) LFREE(rbuf);
    return 2;
}

static int str_format(lua_State*L){
    int n=lua_gettop(L);
    const char*fmt=check_str(L,1);
    int arg=2;
    char*buf=NULL; size_t blen=0,bcap=0;

#define BADD(c) do{if(blen+1>=bcap){bcap=(blen+64)*2;buf=(char*)lm_realloc(buf,bcap);}buf[blen++]=(c);}while(0)
#define BADDSTR(s,l) do{size_t _l=(l);if(blen+_l>=bcap){bcap=(blen+_l+64)*2;buf=(char*)lm_realloc(buf,bcap);}memcpy(buf+blen,s,_l);blen+=_l;}while(0)

    while(*fmt){
        if(*fmt!='%'){BADD(*fmt++);continue;}
        fmt++;
        if(*fmt=='%'){BADD('%');fmt++;continue;}
        /* Format spec */
        char spec[32]={'%'};
        int si=1;
        /* Flags */
        while(*fmt&&strchr("-+ #0",*fmt)) spec[si++]=*fmt++;
        /* Width */
        while(*fmt&&isdigit((unsigned char)*fmt)) spec[si++]=*fmt++;
        /* Precision */
        if(*fmt=='.'){spec[si++]=*fmt++;while(*fmt&&isdigit((unsigned char)*fmt)) spec[si++]=*fmt++;}
        char conv=*fmt++;
        spec[si++]=conv; spec[si]='\0';

        char tmp[512];
        switch(conv){
        case 'd': case 'i': {
            lua_Number v=check_num(L,arg++);
            /* Replace conv with right type */
            char spec2[32]; strcpy(spec2,spec);
            spec2[si-1]='d';
            snprintf(tmp,sizeof(tmp),spec2,(long long)(int64_t)v);
            BADDSTR(tmp,strlen(tmp)); break;
        }
        case 'u': {
            lua_Number v=check_num(L,arg++);
            char spec2[32]; strcpy(spec2,spec);
            spec2[si-1]='u';
            snprintf(tmp,sizeof(tmp),spec2,(unsigned long long)(uint64_t)v);
            BADDSTR(tmp,strlen(tmp)); break;
        }
        case 'o': {
            lua_Number v=check_num(L,arg++);
            char spec2[32]; strcpy(spec2,spec);
            spec2[si-1]='o';
            snprintf(tmp,sizeof(tmp),spec2,(unsigned long long)(uint64_t)v);
            BADDSTR(tmp,strlen(tmp)); break;
        }
        case 'x': {
            lua_Number v=check_num(L,arg++);
            char spec2[32]; strcpy(spec2,spec);
            spec2[si-1]='x';
            snprintf(tmp,sizeof(tmp),spec2,(unsigned long long)(uint64_t)v);
            BADDSTR(tmp,strlen(tmp)); break;
        }
        case 'X': {
            lua_Number v=check_num(L,arg++);
            char spec2[32]; strcpy(spec2,spec);
            spec2[si-1]='X';
            snprintf(tmp,sizeof(tmp),spec2,(unsigned long long)(uint64_t)v);
            BADDSTR(tmp,strlen(tmp)); break;
        }
        case 'e': case 'E': case 'f': case 'g': case 'G': {
            lua_Number v=check_num(L,arg++);
            snprintf(tmp,sizeof(tmp),spec,v);
            BADDSTR(tmp,strlen(tmp)); break;
        }
        case 's': {
            size_t slen;
            const char*sv;
            TVal*tv=stk_at(L,arg++);
            /* Convert to string first */
            if(IS_TAB(tv)||IS_UD(tv)){
                TVal*mm=get_metamethod(L,tv,TM_TOSTRING);
                if(mm&&IS_FUNC(mm)){
                    TVal args[1]; SET_VAL(&args[0],tv);
                    TVal res; SET_NIL(&res);
                    eval_call(L,FUNC_VAL(mm),args,1,&res,1);
                    char buf2[64];
                    sv=val_tostr(L,&res,buf2,sizeof(buf2));
                    Str*s2=s_newz(L,sv); sv=str_val(s2); slen=s2->len;
                    goto do_str_fmt;
                }
            }
            sv=str_from_val(L,tv,&slen);
            if(!sv){char buf2[64];sv=val_tostr(L,tv,buf2,sizeof(buf2));slen=strlen(sv);}
            do_str_fmt:
            /* Check if there's a precision */
            if(strchr(spec,'.')){
                snprintf(tmp,sizeof(tmp),spec,sv);
                BADDSTR(tmp,strlen(tmp));
            }else{
                snprintf(tmp,sizeof(tmp),spec,sv);
                BADDSTR(tmp,strlen(tmp));
            }
            break;
        }
        case 'c': {
            int v=check_int(L,arg++);
            snprintf(tmp,sizeof(tmp),spec,v);
            BADDSTR(tmp,strlen(tmp)); break;
        }
        case 'q': {
            const char*sv=check_str(L,arg++);
            BADD('"');
            while(*sv){
                if(*sv=='"'||*sv=='\\'||*sv=='\0'){BADD('\\');BADD(*sv);}
                else if(*sv=='\n'){BADD('\\');BADD('\n');}
                else if(*sv=='\r'){BADD('\\');BADD('r');}
                else if(*sv=='\0'){BADD('\\');BADD('0');}
                else BADD(*sv);
                sv++;
            }
            BADD('"'); break;
        }
        default:
            luaG_runerror(L,"invalid format option '%c'",conv);
        }
    }
    if(buf) buf[blen]='\0';
    lua_pushlstring(L,buf?buf:"",blen);
    if(buf) LFREE(buf);
    return 1;
}

