/* ===== IO LIBRARY ===== */
typedef struct FileUD { FILE*f; int closed; int is_std; } FileUD;

static FileUD*check_file(lua_State*L,int idx){
    TVal*v=stk_at(L,idx);
    if(!v||!IS_UD(v)){
        lua_pushstring(L,"file expected");
        lua_error(L);
    }
    FileUD*fd=(FileUD*)udata_ptr(UD_VAL(v));
    if(fd->closed && !fd->is_std){
        lua_pushstring(L,"attempt to use a closed file");
        lua_error(L);
    }
    return fd;
}

static void push_file(lua_State*L,FILE*f,int is_std){
    FileUD*fd=(FileUD*)lua_newuserdata(L,sizeof(FileUD));
    fd->f=f; fd->closed=(f==NULL?1:0); fd->is_std=is_std;
    /* Set file metatable */
    lua_getfield(L,LUA_REGISTRYINDEX,"__filemt");
    if(!lua_isnil(L,-1)) lua_setmetatable(L,-2);
    else lua_pop(L,1);
}

static int file_read(lua_State*L){
    FileUD*fd=check_file(L,1);
    const char*fmt=opt_str(L,2,"*l");
    if(*fmt=='*') fmt++;
    if(*fmt=='l'||*fmt=='L'){
        /* Read line */
