            if(total+1>=rcap){rcap=(total+256)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
            rbuf[total++]=(char)c;
        }
        if(c=='\n'&&include_nl){
            if(total+1>=rcap){rcap=(total+8)*2;rbuf=(char*)lm_realloc(rbuf,rcap);}
            rbuf[total++]='\n';
        }
        if(total==0&&c==EOF){lua_pushnil(L);if(rbuf)LFREE(rbuf);return 1;}
        lua_pushlstring(L,rbuf?rbuf:"",total);
        if(rbuf) LFREE(rbuf);
        return 1;
