static int os_date(lua_State*L){
    const char*fmt=opt_str(L,1,"%c");
    time_t t=(time_t)opt_num(L,2,(double)time(NULL));
    int utc=0;
    if(fmt[0]=='!'){fmt++;utc=1;}
