        lua_pushstring(L,"cannot resume non-suspended coroutine");
        return 2;
    }
    /* Get args */
    TVal args[256]; int nargs=n-1;
    for(int i=0;i<nargs&&i<256;i++) SET_VAL(&args[i],stk_at(L,i+2));

    co->resumer=L;
    co->coro_status=2; /* running */

    /* Get the function from stack[0] */
    Func*fn=NULL;
    if(co->top>co->stk&&IS_FUNC(co->stk)) fn=FUNC_VAL(co->stk);

    if(!fn){
        lua_pushboolean(L,0);
        lua_pushstring(L,"coroutine has no function");
        co->coro_status=3;
        return 2;
    }

    /* Execute coroutine */
    TVal ret[256];
    LErr err; err.prev=L->err; err.st=LUA_OK;
    L->err=&err;
    int r=setjmp(err.jb);
    if(r==0){
        /* Call the coroutine function */
        eval_call(co,fn,args,nargs,ret,LUA_MULTRET);
        co->coro_status=3; /* dead */
    }else{
        co->coro_status=3;
        L->err=err.prev;
        /* Error */
        lua_pushboolean(L,0);
        if(co->top>co->stk) SET_VAL(L->top,co->top-1);
        else SET_STR(L->top,s_newz(L,"error in coroutine"));
        L->top++;
        return 2;
    }
    L->err=err.prev;

    int nr=co->coro_nresults;
    lua_pushboolean(L,1);
    for(int i=0;i<nr;i++){
        CHK_STK(L,1); SET_VAL(L->top,&ret[i]); L->top++;
    }
    return 1+nr;
}

static int coro_status(lua_State*L){
    TVal*thr_v=stk_at(L,1);
    if(!thr_v||!IS_THREAD(thr_v)){
        lua_pushstring(L,"dead"); return 1;
    }
    lua_State*co=THR_VAL(thr_v);
    switch(co->coro_status){
    case 0: case 1: lua_pushstring(L,"suspended"); break;
    case 2:
        if(co==L) lua_pushstring(L,"running");
        else lua_pushstring(L,"normal");
        break;
    case 3: lua_pushstring(L,"dead"); break;
    default: lua_pushstring(L,"dead"); break;
    }
    return 1;
}

static int coro_isyieldable(lua_State*L){
    lua_pushboolean(L,0); return 1;
}
static int coro_running(lua_State*L){
    lua_pushnil(L); lua_pushboolean(L,1); return 2;
}

/* Yield - not easily implemented in tree-walker without continuations */
/* Simple implementation: throw a special error caught by resume */
static int coro_yield(lua_State*L){
    luaG_runerror(L,"attempt to yield from outside a coroutine");
    return 0;
}

static int coro_wrap_iter(lua_State*L){
    TVal*thr_v=&FUNC_VAL(stk_at(L,lua_upvalueindex(1)))->c.upvals[0];
    int n=lua_gettop(L);
    /* Push thread and args */
    CHK_STK(L,2);
    TVal*old_top=L->top;
    SET_VAL(L->top,thr_v); L->top++;
    for(int i=1;i<=n;i++) lua_pushvalue(L,i);
    /* Resume */
    /* Save and restore top */
    L->top=old_top;
    /* Set up args for resume */
    /* Actually let's call coro_resume */
    CHK_STK(L,n+2);
    SET_VAL(L->top,thr_v); L->top++;
    /* Already have args on stack */
    lua_call(L,n+1,LUA_MULTRET);
    /* Check first return (boolean) */
    if(lua_gettop(L)>0&&lua_isboolean(L,1)){
        int ok=lua_toboolean(L,1);
        lua_remove(L,1);
        if(!ok){ luaG_runerror(L,"cannot resume dead coroutine"); }
    }
    return lua_gettop(L);
}

static int coro_wrap(lua_State*L){
    TVal*fn_v=stk_at(L,1);
    if(!fn_v||!IS_FUNC(fn_v)){
        lua_pushstring(L,"function expected"); lua_error(L);
    }
    lua_State*co=coro_new(L,FUNC_VAL(fn_v));
    SET_THREAD(L->top,co); L->top++;
    lua_pushcclosure(L,coro_wrap_iter,1);
    return 1;
}

static void luaopen_coroutine(lua_State*L){
