/* ===== BIT LIBRARY (LuaJIT extension) ===== */
static uint32_t bit_normalize(lua_Number n){
    int64_t i=(int64_t)n;
    return(uint32_t)i;
}
static int bit_tobit(lua_State*L){ lua_pushnumber(L,(lua_Number)(int32_t)bit_normalize(check_num(L,1))); return 1; }
static int bit_tohex(lua_State*L){
    uint32_t n=bit_normalize(check_num(L,1));
    int ndigits=opt_int(L,2,8);
    char fmt[16]; int neg=0;
    if(ndigits<0){ndigits=-ndigits;neg=1;}
    if(ndigits>8) ndigits=8;
    if(neg) snprintf(fmt,sizeof(fmt),"%0*X",ndigits,(unsigned)n);
    else snprintf(fmt,sizeof(fmt),"%0*x",ndigits,(unsigned)n);
