}
static int bit_bnot(lua_State*L){ lua_pushnumber(L,(lua_Number)(int32_t)(~bit_normalize(check_num(L,1)))); return 1; }
static int bit_band(lua_State*L){ int n=lua_gettop(L); uint32_t r=bit_normalize(check_num(L,1)); for(int i=2;i<=n;i++) r&=bit_normalize(check_num(L,i)); lua_pushnumber(L,(lua_Number)(int32_t)r); return 1; }
static int bit_bor(lua_State*L){ int n=lua_gettop(L); uint32_t r=bit_normalize(check_num(L,1)); for(int i=2;i<=n;i++) r|=bit_normalize(check_num(L,i)); lua_pushnumber(L,(lua_Number)(int32_t)r); return 1; }
static int bit_bxor(lua_State*L){ int n=lua_gettop(L); uint32_t r=bit_normalize(check_num(L,1)); for(int i=2;i<=n;i++) r^=bit_normalize(check_num(L,i)); lua_pushnumber(L,(lua_Number)(int32_t)r); return 1; }
static int bit_lshift(lua_State*L){ uint32_t n=bit_normalize(check_num(L,1)); int s=bit_normalize(check_num(L,2))&31; lua_pushnumber(L,(lua_Number)(int32_t)(n<<s)); return 1; }
static int bit_rshift(lua_State*L){ uint32_t n=bit_normalize(check_num(L,1)); int s=bit_normalize(check_num(L,2))&31; lua_pushnumber(L,(lua_Number)(int32_t)(n>>s)); return 1; }
static int bit_arshift(lua_State*L){ int32_t n=(int32_t)bit_normalize(check_num(L,1)); int s=bit_normalize(check_num(L,2))&31; lua_pushnumber(L,(lua_Number)(n>>s)); return 1; }
static int bit_rol(lua_State*L){ uint32_t n=bit_normalize(check_num(L,1)); int s=bit_normalize(check_num(L,2))&31; lua_pushnumber(L,(lua_Number)(int32_t)((n<<s)|(n>>(32-s)))); return 1; }
static int bit_ror(lua_State*L){ uint32_t n=bit_normalize(check_num(L,1)); int s=bit_normalize(check_num(L,2))&31; lua_pushnumber(L,(lua_Number)(int32_t)((n>>s)|(n<<(32-s)))); return 1; }
static int bit_bswap(lua_State*L){ uint32_t n=bit_normalize(check_num(L,1)); n=((n>>24)|(n<<24)|((n>>8)&0xff00)|((n<<8)&0xff0000)); lua_pushnumber(L,(lua_Number)(int32_t)n); return 1; }

