/* ===== STRING.BUFFER LIBRARY ===== */
typedef struct SBuf { char*data; size_t len,cap; } SBuf;

static SBuf*get_sbuf(lua_State*L,int idx){
    TVal*v=stk_at(L,idx);
    if(!v||!IS_UD(v)){
        lua_pushstring(L,"string buffer expected"); lua_error(L);
    }
    return (SBuf*)udata_ptr(UD_VAL(v));
}

static int sbuf_new(lua_State*L){
    size_t initcap=opt_int(L,1,64);
    Udata*ud=(Udata*)lm_alloc(sizeof(Udata)+sizeof(SBuf));
    ud->type=LUA_TUD; ud->gc_mark=0; ud->mt=NULL; ud->sz=sizeof(SBuf);
    SBuf*sb=(SBuf*)udata_ptr(ud);
    sb->data=(char*)lm_alloc(initcap+1); sb->len=0; sb->cap=initcap;
    /* Set metatable */
    TVal*bmtv=tab_rawget_s(G(L)->reg,s_newz(L,"__strbufmt"));
    if(bmtv&&IS_TAB(bmtv)) ud->mt=TAB_VAL(bmtv);
    G(L)->allgc=(GCObj*)ud;
    SET_UD(L->top,ud); L->top++;
    return 1;
}

static int sbuf_put(lua_State*L){
    SBuf*sb=get_sbuf(L,1);
    int n=lua_gettop(L);
    for(int i=2;i<=n;i++){
        size_t len; const char*s=lua_tolstring(L,i,&len);
        if(!s) continue;
        if(sb->len+len>=sb->cap){
            sb->cap=(sb->len+len+64)*2;
            sb->data=(char*)lm_realloc(sb->data,sb->cap+1);
        }
        memcpy(sb->data+sb->len,s,len); sb->len+=len;
    }
    lua_pushvalue(L,1); return 1;
}

static int sbuf_get(lua_State*L){
    SBuf*sb=get_sbuf(L,1);
    lua_pushlstring(L,sb->data,sb->len);
    sb->len=0;
    return 1;
}

static int sbuf_tostring(lua_State*L){
    SBuf*sb=get_sbuf(L,1);
    lua_pushlstring(L,sb->data,sb->len);
    return 1;
}

static int sbuf_len(lua_State*L){
    SBuf*sb=get_sbuf(L,1);
    lua_pushnumber(L,(double)sb->len);
    return 1;
}

static int sbuf_reset(lua_State*L){
    SBuf*sb=get_sbuf(L,1);
    sb->len=0;
    lua_pushvalue(L,1); return 1;
}

static void luaopen_string_buffer(lua_State*L){
    Tab*mt=tab_new(L);
    settabfield(L,mt,"put",sbuf_put);
    settabfield(L,mt,"get",sbuf_get);
    settabfield(L,mt,"tostring",sbuf_tostring);
    settabfield(L,mt,"len",sbuf_len);
    settabfield(L,mt,"reset",sbuf_reset);
    settabfield(L,mt,"__tostring",sbuf_tostring);
    TVal mtv; SET_TAB(&mtv,mt);
    tab_rawset_s(L,mt,s_newz(L,"__index"),&mtv);
    tab_rawset_s(L,G(L)->reg,s_newz(L,"__strbufmt"),&mtv);

    Tab*t=tab_new(L);
    settabfield(L,t,"new",sbuf_new);
    TVal tv; SET_TAB(&tv,t);
    /* Store in package.loaded as "string.buffer" */
    TVal*pkg=tab_rawget_s(TAB_VAL(&L->globals),s_newz(L,"package"));
