    settabfield(L,mt,"__tostring",sbuf_tostring);
    TVal mtv; SET_TAB(&mtv,mt);
    tab_rawset_s(L,mt,s_newz(L,"__index"),&mtv);
    tab_rawset_s(L,G(L)->reg,s_newz(L,"__strbufmt"),&mtv);

    Tab*t=tab_new(L);
    settabfield(L,t,"new",sbuf_new);
    TVal tv; SET_TAB(&tv,t);
    /* Store in package.loaded as "string.buffer" */
    TVal*pkg=tab_rawget_s(TAB_VAL(&L->globals),s_newz(L,"package"));
