        TVal*loaded=tab_rawget_s(TAB_VAL(pkg),s_newz(L,"loaded"));
        if(loaded&&IS_TAB(loaded)) tab_rawset_s(L,TAB_VAL(loaded),s_newz(L,"string.buffer"),&tv);
    }
}

