/* ===== PACKAGE LIBRARY ===== */
static int lua_require_f(lua_State*L){
    const char*name=check_str(L,1);
    /* Check package.loaded */
    TVal*pkg=tab_rawget_s(TAB_VAL(&L->globals),s_newz(L,"package"));
    if(pkg&&IS_TAB(pkg)){
        TVal*loaded=tab_rawget_s(TAB_VAL(pkg),s_newz(L,"loaded"));
        if(loaded&&IS_TAB(loaded)){
            TVal*v=tab_rawget_s(TAB_VAL(loaded),s_newz(L,name));
            if(v&&!IS_NIL(v)){ SET_VAL(L->top,v); L->top++; return 1; }
        }
    }
    /* Try to load from preload */
    if(pkg&&IS_TAB(pkg)){
        TVal*preload=tab_rawget_s(TAB_VAL(pkg),s_newz(L,"preload"));
        if(preload&&IS_TAB(preload)){
            TVal*v=tab_rawget_s(TAB_VAL(preload),s_newz(L,name));
            if(v&&IS_FUNC(v)){
                TVal args[1]; SET_STR(&args[0],s_newz(L,name));
                TVal ret; SET_NIL(&ret);
                eval_call(L,FUNC_VAL(v),args,1,&ret,1);
                /* Store in loaded */
                if(pkg&&IS_TAB(pkg)){
                    TVal*loaded=tab_rawget_s(TAB_VAL(pkg),s_newz(L,"loaded"));
                    if(loaded&&IS_TAB(loaded)) tab_rawset_s(L,TAB_VAL(loaded),s_newz(L,name),&ret);
                }
                SET_VAL(L->top,&ret); L->top++;
                return 1;
            }
        }
    }
    /* Try to load from file */
    /* Build search paths */
    const char*path="./?.lua;/usr/local/share/luajit-2.1/?.lua;/usr/local/share/lua/5.1/?.lua;/usr/local/share/lua/5.1/?/init.lua";
    if(pkg&&IS_TAB(pkg)){
        TVal*pv=tab_rawget_s(TAB_VAL(pkg),s_newz(L,"path"));
        if(pv&&IS_STR(pv)) path=str_val(STR_VAL(pv));
    }
    /* Replace ? with module name (. -> /) */
    char modpath[256]; snprintf(modpath,sizeof(modpath),"%s",name);
    for(char*p=modpath;*p;p++) if(*p=='.') *p='/';

    char tried[4096]=""; size_t tlen=0;
    const char*p=path;
    while(*p){
        const char*end=strchr(p,';');
        if(!end) end=p+strlen(p);
        /* Build filename */
        char fn[512];
        int pos=0;
        for(const char*pp=p;pp<end;pp++){
            if(*pp=='?'){
                size_t ml=strlen(modpath);
                if(pos+ml<sizeof(fn)){memcpy(fn+pos,modpath,ml);pos+=ml;}
            }else if(pos<(int)sizeof(fn)-1) fn[pos++]=*pp;
        }
        fn[pos]='\0';
        /* Try to open */
        FILE*f=fopen(fn,"r");
        if(f){
            fclose(f);
            int r=luaL_loadfile(L,fn);
            if(r==LUA_OK){
                TVal args[1]; SET_STR(&args[0],s_newz(L,name));
                TVal ret; SET_BOOL(&ret,1);
                eval_call(L,FUNC_VAL(stk_at(L,-1)),args,1,&ret,1);
                L->top--;
                /* Store in loaded */
                if(pkg&&IS_TAB(pkg)){
                    TVal*loaded=tab_rawget_s(TAB_VAL(pkg),s_newz(L,"loaded"));
                    if(loaded&&IS_TAB(loaded)){
                        TVal*existing=tab_rawget_s(TAB_VAL(loaded),s_newz(L,name));
                        if(!existing||IS_NIL(existing))
                            tab_rawset_s(L,TAB_VAL(loaded),s_newz(L,name),IS_BOOL(&ret)&&B_VAL(&ret)?&ret:&ret);
                    }
                }
                TVal*loaded_v=NULL;
                if(pkg&&IS_TAB(pkg)){
                    TVal*loaded=tab_rawget_s(TAB_VAL(pkg),s_newz(L,"loaded"));
                    if(loaded&&IS_TAB(loaded)) loaded_v=tab_rawget_s(TAB_VAL(loaded),s_newz(L,name));
                }
                if(loaded_v&&!IS_NIL(loaded_v)) SET_VAL(L->top,loaded_v);
                else{SET_BOOL(L->top,1);}
                L->top++;
                return 1;
            }
        }
        /* Record attempt */
        tlen+=snprintf(tried+tlen,sizeof(tried)-tlen,"\n\tno file '%s'",fn);
        p=*end?end+1:end;
    }

    luaG_runerror(L,"module '%s' not found:%s",name,tried);
    return 0;
}

