/* print usage */
static void print_usage(const char*prog){
    fprintf(stderr,"usage: %s [options]... [script [args]...].\n",prog);
    fprintf(stderr,"Available options are:\n");
    fprintf(stderr,"  -e chunk  Execute string 'chunk'.\n");
    fprintf(stderr,"  -l name   Require library 'name'.\n");
    fprintf(stderr,"  -b ...    Save or list bytecode.\n");
    fprintf(stderr,"  -j cmd    Perform LuaJIT control command.\n");
    fprintf(stderr,"  -O[opt]   Control LuaJIT optimizations.\n");
    fprintf(stderr,"  -i        Enter interactive mode after executing 'script'.\n");
    fprintf(stderr,"  -v        Show version information.\n");
    fprintf(stderr,"  -E        Ignore environment variables.\n");
    fprintf(stderr,"  --        Stop handling options.\n");
    fprintf(stderr,"  -         Execute stdin and stop handling options.\n");
}

/* Check if environment should be ignored */
static int ignore_env=0;

/* Initialize LUA_PATH etc. from environment */
static void init_env(lua_State*L){
    if(ignore_env) return;
    /* LUA_PATH */
    const char*path=getenv("LUA_PATH");
    if(path){
        TVal*pkg=tab_rawget_s(TAB_VAL(&L->globals),s_newz(L,"package"));
        if(pkg&&IS_TAB(pkg))
            tab_rawset_s(L,TAB_VAL(pkg),s_newz(L,"path"),
                         (TVal*)&(TVal){.v.gc=(GCObj*)s_newz(L,path),.t=LUA_TSTR});
    }
    const char*cpath=getenv("LUA_CPATH");
    if(cpath){
        TVal*pkg=tab_rawget_s(TAB_VAL(&L->globals),s_newz(L,"package"));
        if(pkg&&IS_TAB(pkg)){
            TVal v; SET_STR(&v,s_newz(L,cpath));
            tab_rawset_s(L,TAB_VAL(pkg),s_newz(L,"cpath"),&v);
        }
    }
}

/* Handle -j command */
static int handle_jcmd(lua_State*L,const char*cmd){
    if(!strcmp(cmd,"on")){ jit_on(L); return 0; }
    if(!strcmp(cmd,"off")){ jit_off(L); return 0; }
    if(!strcmp(cmd,"flush")){ jit_flush(L); return 0; }
    /* For jit.v, jit.dump, jit.p - these are modules */
    /* Return error since we don't have them */
    fprintf(stderr,"%s: unknown luaJIT command or jit.* modules not installed\n","./executable");
    return 1;
}

/* Handle -b bytecode command */
static int handle_bcmd(lua_State*L,const char**argv,int argc){
    /* -b[options] input output */
    /* Since we don't support bytecode saving, just error */
    fprintf(stderr,"%s: unknown luaJIT command or jit.* modules not installed\n","./executable");
    return 1;
}

int main(int argc,char**argv){
    setlocale(LC_ALL,"C");

    lua_State*L=lua_newstate();
    luaL_openlibs(L);

    /* Seed random with time */
    rng_state=(uint64_t)time(NULL);

    int i=1;
    int interactive=0;
    int had_script=0;
    int had_e=0;
    int had_error=0;

    /* Store program name */
    if(argc>0){
        TVal v; SET_STR(&v,s_newz(L,argv[0]));
        tab_rawset_s(L,TAB_VAL(&L->globals),s_newz(L,"arg"),
                     (TVal*)&(TVal){.t=LUA_TNIL});
        /* arg table will be set when script is executed */
    }

    /* Process args */
    while(i<argc){
        const char*a=argv[i];
        if(a[0]!='-'||a[1]=='\0'){
            /* Script or stdin */
            break;
        }
        if(!strcmp(a,"--")){ i++; break; }
        if(!strcmp(a,"-")){ break; }
        if(!strcmp(a,"-v")){
            printf("%s -- %s %s\n",LJ_VERSION_STR,LJ_COPYRIGHT,LJ_URL);
            i++;
            continue;
        }
        if(!strcmp(a,"-i")){ interactive=1; i++; continue; }
        if(!strcmp(a,"-E")){ ignore_env=1; i++; continue; }
        if(a[1]=='e'){
            const char*chunk=a[2]?a+2:argv[++i];
            if(!chunk){ fprintf(stderr,"%s: option '-e' requires argument\n",argv[0]); return 1; }
            i++;
            /* Set up arg table with no script */
            if(!had_e&&!had_script){
                Tab*at=tab_new(L);
                TVal v; SET_STR(&v,s_newz(L,argv[0]));
                tab_rawset_i(L,at,-1,&v);
                TVal atv; SET_TAB(&atv,at);
                tab_rawset_s(L,TAB_VAL(&L->globals),s_newz(L,"arg"),&atv);
                init_env(L);
            }
            had_e=1;
            if(exec_string(L,chunk,"(command line)")) had_error=1;
            continue;
        }
        if(a[1]=='l'){
            const char*lib=a[2]?a+2:argv[++i];
            if(!lib){ fprintf(stderr,"%s: option '-l' requires argument\n",argv[0]); return 1; }
            i++;
            /* require(lib) */
            TVal*req=tab_rawget_s(TAB_VAL(&L->globals),s_newz(L,"require"));
            if(req&&IS_FUNC(req)){
                TVal args[1]; SET_STR(&args[0],s_newz(L,lib));
                TVal ret; SET_NIL(&ret);
                LErr err; err.prev=L->err; err.st=LUA_OK;
                L->err=&err;
                int er=setjmp(err.jb);
                if(er==0) eval_call(L,FUNC_VAL(req),args,1,&ret,1);
                else{
                    L->err=err.prev;
                    if(L->top>L->stk){
                        char buf[256]; fprintf(stderr,"%s: %s\n",argv[0],val_tostr(L,L->top-1,buf,sizeof(buf)));
                        L->top--;
                    }
                    had_error=1;
                }
                L->err=err.prev;
            }
            continue;
        }
        if(a[1]=='b'){
            /* Bytecode command */
            return handle_bcmd(L,NULL,0);
        }
        if(a[1]=='j'){
            const char*cmd=a[2]?a+2:argv[++i];
            if(!cmd){ fprintf(stderr,"%s: option '-j' requires argument\n",argv[0]); return 1; }
            i++;
            if(handle_jcmd(L,cmd)) return 1;
            continue;
        }
        if(a[1]=='O'){
            /* Optimization options - ignore */
            i++;
            continue;
        }
        /* Unknown option */
        fprintf(stderr,"%s: unrecognized option '%s'\n",argv[0],a);
        print_usage(argv[0]);
        return 1;
    }

    /* Script or stdin */
    if(i<argc){
        const char*script=argv[i];
        int script_argc=argc-i-1;
        char**script_argv=argv+i+1;

        if(!strcmp(script,"-")){
            /* stdin */
            init_env(L);
            int r=exec_file(L,NULL,argv,script_argc,i+1);
            if(r) had_error=1;
        }else{
            init_env(L);
            int r=exec_file(L,script,argv,script_argc,i+1);
            if(r) had_error=1;
        }
        had_script=1;
        i=argc;
    }

    /* Interactive mode */
    if(interactive||(!had_script&&!had_e&&!had_error)){
        if(!had_script&&!had_e) init_env(L);
        do_interactive(L);
    }

    return had_error?1:0;
}

