# The problem is in the logic for handling "main position occupied":
# When mn->key is nil, we go to the else branch: fr->next=mn->next; mn->next=fr;
# We put k in fr, not mn. And mn (which is nil) now points to fr.
# 
# But the search starts at mn! First check: mn->key == k? mn has nil key, fails.
# Then follow mn->next = fr. fr->key == k? Yes! Returns &fr->val.
# 
# But this means:
# - mn is a "zombie" node that points to fr
# - This wastes a node (mn) even though it's empty
# - When we insert more keys that hash to mn, they think mn is occupied
# 
# The REAL fix: when mn->key is nil (main slot is free), put k directly in mn!
# 
# Let me fix this:

python3 << 'PYEOF'
with open('/workspace/src/lua.c', 'r') as f:
    content = f.read()

old = '''    TabNode*fr=tab_getfree(t);
    if(!fr){tab_resize(L,t,t->arrsize,node_size(t)*2);tab_rawset(L,t,k,v);return;}
    TabNode*mn=tab_hash(t,k);
    if(!IS_NIL(&mn->key)&&tab_hash(t,&mn->key)!=mn){
        SET_VAL(&fr->key,&mn->key);SET_VAL(&fr->val,&mn->val);
        fr->next=mn->next;mn->next=NULL;
        SET_NIL(&mn->key);SET_NIL(&mn->val);fr=mn;
    }else{fr->next=mn->next;mn->next=fr;}
    SET_VAL(&fr->key,k);SET_VAL(&fr->val,v);'''

new = '''    TabNode*mn=tab_hash(t,k);
    if(IS_NIL(&mn->key)){
        /* Main position is free - use it directly */
        SET_VAL(&mn->key,k);SET_VAL(&mn->val,v);mn->next=NULL;
        return;
    }
    TabNode*fr=tab_getfree(t);
    if(!fr){tab_resize(L,t,t->arrsize,node_size(t)*2);tab_rawset(L,t,k,v);return;}
    if(tab_hash(t,&mn->key)!=mn){
        /* mn is occupied by a collider - move collider to fr */
        SET_VAL(&fr->key,&mn->key);SET_VAL(&fr->val,&mn->val);
        fr->next=mn->next;
        /* Update the previous node in the chain of the collider's main pos */
        TabNode*pmn=tab_hash(t,&fr->key);
        while(pmn->next&&pmn->next!=mn) pmn=pmn->next;
        if(pmn->next==mn) pmn->next=fr;
        mn->next=NULL;
        SET_VAL(&mn->key,k);SET_VAL(&mn->val,v);
    }else{
        /* mn is correctly placed - add fr to chain */
        fr->next=mn->next;mn->next=fr;
        SET_VAL(&fr->key,k);SET_VAL(&fr->val,v);
    }'''

content = content.replace(old, new)
with open('/workspace/src/lua.c', 'w') as f:
    f.write(content)
print("Fixed")
