# 
# BUT! The key issue is: in eval_call for C functions:
# TVal*base = L->top;  // save BEFORE pushing func+args
# SET_FUNC(L->top, fn); L->top++;
# for args: SET_VAL(L->top, &args[i]); L->top++;
# TVal*func_slot = L->top-1; // this is wrong! After args are pushed...
# Wait:
# base = L->top (before func push)
# SET_FUNC(L->top, fn); L->top++; // func_slot = base+0
# TVal*func_slot = L->top-1; // = base+0 = func
# Correct!
# L->base = func_slot+1; // = base+1
# Push args: L->top goes to base+1+nargs
# 
# After C func returns:
# results = L->top - nr
# BUT: if the C function called CHK_STK which reallocated the stack,
# then 'base' (which is a TVal* saved before realloc) is now STALE!
# 
# THIS IS THE BUG! `base` is a TVal* that might become stale after stack realloc.
# 
# When push_captures calls lua_pushlstring -> CHK_STK -> stk_grow -> stk_realloc,
# the stack is reallocated. L->stk, L->top, L->base are all updated.
# But `base` is a local variable in eval_call that's still pointing to old memory!
# 
# After realloc:
# - L->stk is new allocation
# - L->base = new_stk + based (correctly updated)
# - But `base` still points to old_stk + base_offset!
# 
# So L->top = new address, but base = old address.
# L->top = base causes L->top to be set to an invalid old address!
# 
# Fix: save 'base' as an offset, not a pointer!

python3 << 'PYEOF'
with open('/workspace/src/lua.c', 'r') as f:
    content = f.read()

# Fix the eval_call C function call to use offsets
old = '''    if(fn->c.is_c==1){
        /* C function */
        /* Set up stack for C call */
        CHK_STK(L,nargs+20);
        TVal*base=L->top;
        /* Push a dummy function slot */
        SET_FUNC(L->top,fn); L->top++;
        TVal*func_slot=L->top-1;
        /* Push args */
        for(int i=0;i<nargs;i++){ SET_VAL(L->top,&args[i]); L->top++; }
        TVal*old_base=L->base;
        L->base=func_slot+1;
        int old_top_offset=(int)(L->top-L->stk);
        /* Push CI */
        CI*ci=ci_push(L);
        ci->func=func_slot;
        ci->base=L->base;
        ci->top=L->top;
        ci->savedpc=NULL;
        ci->nr=nret;
        CI*old_ci=L->ci;
        /* Call the C function */
        int nr=fn->c.f(L);
        L->ci=old_ci-1; if(L->ci<L->ci0)L->ci=L->ci0;
        /* Collect results */
        TVal*results=L->top-nr;
        if(nret>=0){
            for(int i=0;i<nret&&i<nr;i++) SET_VAL(&ret[i],&results[i]);
            for(int i=nr;i<nret;i++) SET_NIL(&ret[i]);
        }else{
            /* LUA_MULTRET */
            for(int i=0;i<nr;i++) SET_VAL(&ret[i],&results[i]);
            L->coro_nresults = nr;
        }
        L->top=base;
        L->base=old_base;
        L->ncC--;'''

new = '''    if(fn->c.is_c==1){
        /* C function */
        /* Set up stack for C call */
        CHK_STK(L,nargs+20);
        /* Save offsets (not pointers - stack may be reallocated) */
        ptrdiff_t base_offset=(ptrdiff_t)(L->top-L->stk);
        ptrdiff_t old_base_offset=(ptrdiff_t)(L->base-L->stk);
        /* Push a dummy function slot */
        SET_FUNC(L->top,fn); L->top++;
        /* Push args */
        for(int i=0;i<nargs;i++){ CHK_STK(L,1); SET_VAL(L->top,&args[i]); L->top++; }
        /* Set base after args are pushed */
        L->base=L->stk+base_offset+1;
