        CI*ci=ci_push(L);
        ci->func=L->stk+base_offset;
        ci->base=L->base;
        ci->top=L->top;
        ci->savedpc=NULL;
        ci->nr=nret;
        /* Call the C function */
        int nr=fn->c.f(L);
