            for(int i=nr;i<nret;i++) SET_NIL(&ret[i]);
        }else{
            /* LUA_MULTRET */
            for(int i=0;i<nr;i++) SET_VAL(&ret[i],&results[i]);
            L->coro_nresults = nr;
        }
        /* Restore stack (using saved offsets) */
        L->top=L->stk+base_offset;
        L->base=L->stk+old_base_offset;
        L->ncC--;'''

