# The string itself is garbage! '^^V' - the str_data(ts) after s_new already has garbage!
# The issue is in push_captures: when we call s_new(L, ms->capture[i].init, len),
# ms->capture[i].init points into the source string's data.
# 
# BUT: s_new(L, src, len) calls s_intern(L, src, len) which might reallocate strt.hash!
# During strt resize, we call lm_realloc which might move the strt hash table.
# BUT the STRING DATA (ms->capture[i].init) points into a DIFFERENT Str object's data.
# That Str object is in allgc but its data is not moved by strt resize.
# 
# However! s_intern first COPIES the data: memcpy(str_data(ts), s, len).
# So ts->data should be "hel". But we see garbage.
# 
# Unless str_data(ts) is wrong. Let me check:
# str_data(ts) = (char*)((ts)+1) = address after the Str struct.
# The Str was just malloc'd: ts = lm_alloc(sizeof(Str)+len+1).
# So ts+1 = first byte after Str struct = start of data.
# memcpy(str_data(ts), s, len) copies "hel" there.
# str_data(ts)[len] = '\0'.
# 
# BUT WAIT! s_intern has a bug: it first creates the Str, adds it to strt.h[slot],
# then does "ts->next = g->allgc; g->allgc = (GCObj*)ts;"
# 
# BUT it already set ts->next to g->strt.h[slot] which is the old hash bucket!
# Now ts->next is OVERWRITTEN to g->allgc!
# 
# This means the strt hash chain is broken - ts is no longer in strt.h[slot]!
# 
# That would cause duplicate strings but not garbage data.
# 
# Actually wait - when s_intern grows the strt table (count > size*2),
# it allocates a NEW hash table and copies all strings into it.
# During this process, ts->next is modified to point into the new hash table.
# But ts was just created and ts->next was set to strt.h[slot].
# Then g->allgc sets ts->next to the old allgc head.
# So in the strt.h[slot] chain, the original head (before ts was inserted) is still there,
# but ts->next no longer points to it!
# 
# Actually in the current code of s_intern:
# ts->next = (GCObj*)g->strt.h[slot]; -- ts inserted into strt chain
# g->strt.h[slot] = ts; -- strt chain head updated
# g->strt.n++;
# /* grow strt if needed */
# if(g->strt.n > g->strt.sz*2){
#     strt_resize...  <- this modifies ts->next!
# }
# /* Add to allgc */
# ts->next = g->allgc; -- OVERWRITES the strt chain pointer!
# g->allgc = (GCObj*)ts;
# 
# FOUND IT! The last two lines:
# ts->next = g->allgc;  // This DESTROYS the strt chain!
# g->allgc = (GCObj*)ts;
# 
# When s_intern was first written with a different data structure, allgc and strt.h
# used the same `next` field. But now GCObj.next is shared between allgc chain and strt chain!
# 
# We can't use the same `next` field for both chains!
# 
# Fix: either use a separate allgc pointer in Str, or just don't put strings in allgc.
# Since we're doing simple garbage collection (or none), let's just remove the allgc addition.

python3 << 'PYEOF'
with open('/workspace/src/lua.c', 'r') as f:
    content = f.read()

# Remove the allgc addition in s_intern (it breaks the strt chain)
old = '''    ts->next=(GCObj*)g->strt.h[slot];
    g->strt.h[slot]=ts;
    g->strt.n++;
    /* grow strt if needed */
    if(g->strt.n>g->strt.sz*2){
        int nsz=g->strt.sz*2;
        Str**nh=(Str**)lm_alloc(sizeof(Str*)*nsz);
        memset(nh,0,sizeof(Str*)*nsz);
        for(int i=0;i<g->strt.sz;i++){
            Str*x=g->strt.h[i];
            while(x){Str*nx=(Str*)x->next; int ns2=x->hash&(nsz-1); x->next=(GCObj*)nh[ns2]; nh[ns2]=x; x=nx;}
        }
        LFREE(g->strt.h); g->strt.h=nh; g->strt.sz=nsz;
    }
    /* Add to allgc (strings are never collected for simplicity) */
    ts->next=g->allgc; g->allgc=(GCObj*)ts;
    return ts;'''

new = '''    /* Insert into strt hash chain */
    ts->next=(GCObj*)g->strt.h[slot];
    g->strt.h[slot]=ts;
    g->strt.n++;
    /* grow strt if needed */
    if(g->strt.n>g->strt.sz*2){
        int nsz=g->strt.sz*2;
        Str**nh=(Str**)lm_alloc(sizeof(Str*)*nsz);
        memset(nh,0,sizeof(Str*)*nsz);
        for(int i=0;i<g->strt.sz;i++){
            Str*x=g->strt.h[i];
