        }
        LFREE(g->strt.h); g->strt.h=nh; g->strt.sz=nsz;
    }
    /* Note: strings are kept in strt hash table and NOT added to allgc */
    /* This avoids the conflict between strt chain and allgc chain */
    return ts;'''

content = content.replace(old, new)
with open('/workspace/src/lua.c', 'w') as f:
    f.write(content)
print("Fixed s_intern allgc conflict")
