# When piped, no output. But it should read from stdin and execute!
# In our main, we enter interactive mode only if stdin is a tty.
# But the original reads from stdin even when piped.
# 
# The original behavior:
# - No args -> read from stdin (whether tty or not)
# - If stdin is tty -> interactive mode with prompts
# - If stdin is pipe -> just execute stdin content
# 
# Our current code: if(!had_script&&!had_e&&isatty(0)) -> interactive only for tty
# But we should also read from stdin when it's a pipe!

# Let me fix: when no script and no -e, always read from stdin.
# If stdin is tty: show prompt. If not: just execute silently.

python3 << 'PYEOF'
with open('/workspace/src/lua.c', 'r') as f:
    content = f.read()

# Fix interactive/stdin mode
old = '''    if(interactive||((!had_script&&!had_e)&&isatty(0))){
        if(!had_script&&!had_e) init_env(L);
        /* Print version when entering interactive mode */
        if(!had_version) printf("%s -- %s %s\\n",LJ_VERSION_STR,LJ_COPYRIGHT,LJ_URL);
        do_interactive(L);
    }'''

new = '''    if(interactive||((!had_script&&!had_e)&&isatty(0))){
        if(!had_script&&!had_e) init_env(L);
        /* Print version when entering interactive mode (only if tty) */
        if(isatty(0)&&!had_version) printf("%s -- %s %s\\n",LJ_VERSION_STR,LJ_COPYRIGHT,LJ_URL);
        do_interactive(L);
    }else if(!had_script&&!had_e){
        /* stdin is a pipe - execute silently */
        init_env(L);
        /* Read all stdin and execute */
        char*buf=NULL; size_t total=0;
        char tmp[4096]; size_t nr;
        while((nr=fread(tmp,1,sizeof(tmp),stdin))>0){
            buf=(char*)realloc(buf,total+nr+1);
            memcpy(buf+total,tmp,nr); total+=nr;
        }
        if(buf){
            buf[total]=\'\\0\';
            /* Setup arg table */
            Tab*at=tab_new(L);
            TVal v; SET_STR(&v,s_newz(L,argv[0]));
            tab_rawset_i(L,at,-1,&v);
            TVal atv; SET_TAB(&atv,at);
            tab_rawset_s(L,TAB_VAL(&L->globals),s_newz(L,"arg"),&atv);
            if(exec_string(L,buf,"stdin")) had_error=1;
            free(buf);
        }
    }'''

content = content.replace(old, new)
with open('/workspace/src/lua.c', 'w') as f:
    f.write(content)
print("Fixed stdin reading")
