    luaopen_package(L);
    luaopen_base(L);'''

# Actually let me add to package.loaded for each lib
old = '''    luaopen_coroutine(L);
    luaopen_debug(L);
    luaopen_bit(L);
    luaopen_jit(L);
    luaopen_ffi(L);
    luaopen_string_buffer(L);
}'''

new = '''    luaopen_coroutine(L);
    luaopen_debug(L);
    luaopen_bit(L);
    luaopen_jit(L);
    luaopen_ffi(L);
    luaopen_string_buffer(L);

    /* Register built-in libraries in package.loaded */
    TVal*pkg_loaded=NULL;
    TVal*pkg=tab_rawget_s(TAB_VAL(&L->globals),s_newz(L,"package"));
    if(pkg&&IS_TAB(pkg)) pkg_loaded=tab_rawget_s(TAB_VAL(pkg),s_newz(L,"loaded"));
    if(pkg_loaded&&IS_TAB(pkg_loaded)){
        static const char*builtin_libs[]={"os","io","math","string","table","coroutine","debug","package",NULL};
        for(int i=0;builtin_libs[i];i++){
            TVal*gv=tab_rawget_s(TAB_VAL(&L->globals),s_newz(L,builtin_libs[i]));
            if(gv&&IS_TAB(gv)){
                tab_rawset_s(L,TAB_VAL(pkg_loaded),s_newz(L,builtin_libs[i]),gv);
            }
        }
        /* Add base lib as "_G" equivalent */
        TVal*base_loaded=tab_rawget_s(TAB_VAL(pkg_loaded),s_newz(L,"base"));
        if(!base_loaded||IS_NIL(base_loaded)){
            TVal v; SET_BOOL(&v,1);
            tab_rawset_s(L,TAB_VAL(pkg_loaded),s_newz(L,"base"),&v);
        }
    }
}'''

content = content.replace(old, new)
